local config = {
  ui_story_5010_50100101_1_dialog_content = "\"Como seres vivos, devemos mostrar amor, compaixão e respeito a todas as vidas.\"",
  ui_story_5010_50100101_2_dialog_content = "\"Como tal, fizemos o que achamos certo e não é necessário nos agradecer.\"",
  ui_story_5010_50100101_3_dialog_content = "\"Fique bem, jovem PlayerName.\"",
  ui_story_5010_50100101_4_dialog_content = "Uau... A carta do <color=#FFB400>Guilda Lin</color> realmente mostra que eles são uma família muito civilizada!",
  ui_story_5010_50100101_5_dialog_content = "Eu deveria tentar escrever uma carta para Vice usando o mesmo estilo algum dia...",
  ui_story_5010_50100101_6_dialog_content = "\"Caro vice, como você tem se saído ultimamente? Você se acostumou com seu regime de treinamento em Illumina?\"",
  ui_story_5010_50100101_7_dialog_content = "\"Independentemente disso, como camaradas, aprender a sutil arte de cozinhar é de extrema importância...\"",
  ui_story_5010_50100101_8_dialog_content = "\"Pássaro rechonchudo! Gordinho!\"",
  ui_story_5010_50100101_9_dialog_content = "Ei! Grosseiro!",
  ui_story_5010_50100101_10_dialog_content = "Hã?",
  ui_story_5010_50100101_11_dialog_content = "Yaaas!",
  ui_story_5010_50100101_12_dialog_content = "Quer ouvir minha piada primeiro?",
  ui_story_5010_50100101_13_dialog_content = "É super-duper-extra engraçado! Yoshi perdeu dois quilos só de rir depois de ouvir isso!",
  ui_story_5010_50100101_14_dialog_content = "Em outra hora, talvez... Ei, você tem uma carta pendurada na sua bolsa aí.",
  ui_story_5010_50100101_15_dialog_content = "Parece que está endereçado a... mim? Aqui, deixe-me ver.",
  ui_story_5010_50100101_16_dialog_content = "Você não tem tempo nem para uma piadinha? Multar!",
  ui_story_5010_50100101_17_dialog_content = "Aqui está sua carta!",
  ui_story_5010_50100101_18_dialog_content = "De <color=#FFB400>senhor das sombras</color> ele mesmo!",
  ui_story_5010_50100101_19_dialog_content = "Eles pediram especificamente que eu assistisse você ler tudo.",
  ui_story_5010_50100101_20_dialog_content = "Então apresse-se! Eu não tenho o dia todo!",
  ui_story_5010_50100101_21_dialog_content = "O-Ok! Eu imagino o que poderia ser? Deve ser muito importante...",
  ui_story_5010_50100101_22_dialog_content = "Caro PlayerName,",
  ui_story_5010_50100101_24_dialog_content = "\"Com base em suas várias ações ...\"",
  ui_story_5010_50100101_25_dialog_content = "\"Tanto a Federação Illumina quanto Lumopolis reconhecem você como o único representante dos Caelestitas. Naturalmente, Umbraton não é exceção...\"",
  ui_story_5010_50100101_26_dialog_content = "Vamos, já! Tenho outras cartas para entregar, sabe!",
  ui_story_5010_50100101_27_dialog_content = "\"Como representante de Umbraton, eu agora declaro que todos os bens caelestitas depositados em Umbraton são de propriedade exclusiva de vocês, o último dos caelestitas...\"",
  ui_story_5010_50100101_28_dialog_content = "\"Você pode usar esta carta como prova de seu direito de reivindicar a propriedade, e a Sede da Guilda Umbraton cuidará de todos os procedimentos logísticos...\"",
  ui_story_5010_50100101_29_dialog_content = "\"A localização da sede é... A pessoa encarregada deste assunto é... As informações de contato do terminal são as seguintes...\"",
  ui_story_5010_50100101_30_dialog_content = "\"... E <color=#FFB400>betel</color> será responsável por acompanhá-lo ao banco da Guilda, bem como providenciar toda a papelada da herança...\"",
  ui_story_5010_50100101_31_dialog_content = "Dezessete vagalumes... dezoito vagalumes...",
  ui_story_5010_50100101_32_dialog_content = "\"Atenciosamente, Istvan.\"",
  ui_story_5010_50100101_33_dialog_content = "Bens celestitas...?",
  ui_story_5010_50100101_34_dialog_content = "Ué... Eh? Que tipo de bens os caelestitas tinham em Umbraton?",
  ui_story_5010_50100101_35_dialog_content = "Sei lá.",
  ui_story_5010_50100101_36_dialog_content = "Então você sabe quanto tempo leva para a Guilda lidar com toda a papelada?",
  ui_story_5010_50100101_37_dialog_content = "Nenhum palpite!",
  ui_story_5010_50100101_38_dialog_content = "Então... Você ao menos sabe quem é esse <color=#FFB400>betel</color> pessoa é?",
  ui_story_5010_50100101_39_dialog_content = "Ah-ha! Eu conheço este!",
  ui_story_5010_50100101_40_dialog_content = "Ela está no comando da sede da Guilda e é a filha adotiva do Shadowlord!",
  ui_story_5010_50100101_41_dialog_content = "Ouvi dizer que ela voltou para Umbraton depois de estudar em Lumopolis, e ela tem alguns cachorrinhos fofos com ela!",
  ui_story_5010_50100101_42_dialog_content = "Filha adotiva? Quantas filhas adotivas o Shadowlord tem...?",
  ui_story_5010_50100101_43_dialog_content = "Meh, isso não é importante!",
  ui_story_5010_50100101_44_dialog_content = "Oh sim! Senhora <color=#FFB400>Naroxel</color> também me pediu para passar uma mensagem para você!",
  ui_story_5010_50100101_45_dialog_content = "Por que ela mesma não me conta...?",
  ui_story_5010_50100101_46_dialog_content = "Ela é muito ocupada, você sabe! Agora escute...",
  ui_story_5010_50100101_47_dialog_content = "\"Saudações, PlayerName.\"",
  ui_story_5010_50100101_48_dialog_content = "\"Chegou ao meu conhecimento que um certo conjunto de <color=#FFB400>componentes da sala de simulação</color> em breve será listado em um leilão clandestino em Umbraton.\"",
  ui_story_5010_50100101_49_dialog_content = "\"Pelo meu próprio entendimento, componentes como esses eram frequentemente usados para modificar ou até atualizar o Colossi.\"",
  ui_story_5010_50100101_50_dialog_content = "\"Se você estiver interessado, pode ser bom vê-los por si mesmo. Talvez eles possam ser úteis para Soroz no futuro?\"",
  ui_story_5010_50100101_51_dialog_content = "\"Que a natureza sempre o proteja... Seu amigo, Naroxel.\"",
  ui_story_5010_50100101_52_dialog_content = "\"<color=#FFB400>Componentes da sala de simulação</color>\"? ... Ei, Eho?",
  ui_story_5010_50100101_53_dialog_content = "Cau? E agora?",
  ui_story_5010_50100101_54_dialog_content = "Você sabe do que se trata o leilão clandestino?",
  ui_story_5010_50100101_55_dialog_content = "Bem, claro que sim! É um leilão, obviamente... E acontece que é underground!",
  ui_story_5010_50100101_56_dialog_content = "Você saberia se fosse ver por si mesmo, certo? Ah, você é tão lento.",
  ui_story_5010_50100101_57_dialog_content = "Vou embora de verdade, agora! Ainda tenho dezoito outras entregas para fazer hoje!",
  ui_story_5010_50100101_58_dialog_content = "Ok, obrigado por... Oh, ela já se foi. Deve ser bom ter asas assim...",
  ui_story_5010_50100101_59_dialog_content = "Hmm... muito em que pensar agora. Preciso de um tempo...",
  ui_story_5010_50100101_60_dialog_content = "A sede da Guilda, o leilão clandestino...",
  ui_story_5010_50100101_61_dialog_content = "Oh! Eu também posso passar na Lin Guild e dizer olá!",
  ui_story_5010_50100101_62_dialog_content = "\"Por favor, entre em contato com o seguinte número através do terminal, e o chefe da Guilda irá encontrá-lo fora de Umbraton...\"",
  ui_story_5010_50100101_63_dialog_content = "Parece que nossa próxima parada é <color=#FFB400>Umbraton</color>!",
  ui_story_5010_50100201_1_dialog_content = "Olá? É isto PlayerName? Aqui é Bethel, da Guilda Umbraton.",
  ui_story_5010_50100201_2_dialog_content = "O-Olá!",
  ui_story_5010_50100201_3_dialog_content = "Por favor, pouse a leste do <color=#FFB400>represa de cicatrizes</color>. te espero lá.",
  ui_story_5010_50100201_4_dialog_content = "Sem problema!",
  ui_story_5010_50100201_5_dialog_content = "Umbraton parece realmente impressionante deste ângulo.",
  ui_story_5010_50100201_6_dialog_content = "Umbraton... Uma cidade conhecida como a Sombra de Lumopolis.",
  ui_story_5010_50100201_7_dialog_content = "<color=#e8d9bb>Em breve estaremos chegando ao nosso destino. Por favor, confirme sua zona de pouso antes da chegada.</color>",
  ui_story_5010_50100201_8_dialog_content = "Oh, não... Esqueci-me totalmente de perguntar onde fica a Represa das Cicatrizes.",
  ui_story_5010_50100201_9_dialog_content = "Acho que vou procurar pessoalmente...",
  ui_story_5010_50100201_10_dialog_content = "Olá de novo. Você deve ser PlayerName. Eu sou Betel.",
  ui_story_5010_50100201_11_dialog_content = "Sim! O-Oi...",
  ui_story_5010_50100201_12_dialog_content = "E este deve ser o Colosso... É tão magnífico quanto dizem as histórias. Imagino que deve ser bem difícil pilotar?",
  ui_story_5010_50100201_13_dialog_content = "Parece que você teve alguma dificuldade para aterrissar.",
  ui_story_5010_50100201_14_dialog_content = "N-Na verdade não, só me perdi um pouco. Eu não venho muito a Umbraton, sabe...",
  ui_story_5010_50100201_15_dialog_content = "Para ser sincero, quase me perdi no caminho até aqui também.",
  ui_story_5010_50100201_16_dialog_content = "Umbraton certamente mudou muito nos últimos anos...",
  ui_story_5010_50100201_17_dialog_content = "Mas o suficiente sobre isso. Por favor, por aqui.",
  ui_story_5010_50100201_18_dialog_content = "(Se eu soubesse que ela seria tão formal, teria me arrumado um pouco...)",
  ui_story_5010_50100201_19_dialog_content = "Então... vamos para a sede agora?",
  ui_story_5010_50100201_20_dialog_content = "Além disso... Você poderia me dizer quais são exatamente esses ativos celestitas?",
  ui_story_5010_50100201_21_dialog_content = "O livro-razão descreve-os como um número de baús. Somente o proprietário está autorizado a abri-los e verificar seu conteúdo.",
  ui_story_5010_50100201_22_dialog_content = "Sede da Guilda de Umbraton... Perdoe-me, mas você gerencia todas as operações da Guilda? Os leilões clandestinos também estão sob sua jurisdição?",
  ui_story_5010_50100201_23_dialog_content = "Leilões clandestinos?",
  ui_story_5010_50100201_24_dialog_content = "Embora eu não tenha ideia de onde você encontrou esse termo, receio ter muito pouca informação para divulgar sobre o assunto.",
  ui_story_5010_50100201_25_dialog_content = "Será que você deseja leiloar os bens celestitas que veio reivindicar?",
  ui_story_5010_50100201_26_dialog_content = "Ah! Eu não quis dizer isso! Acabei de ouvir que alguém está colocando algumas coisas celestitas em leilão... Então pensei em perguntar a você sobre isso.",
  ui_story_5010_50100201_27_dialog_content = "Isso estaria muito abaixo de nós. A Guilda Umbraton nunca se envolveria na venda não autorizada de propriedades de outras pessoas.",
  ui_story_5010_50100201_28_dialog_content = "E-entendi.",
  ui_story_5010_50100201_29_dialog_content = "Por favor, continue, se quiser.",
  ui_story_5010_50100201_30_dialog_content = "...",
  ui_story_5010_50100201_31_dialog_content = "(Sinto que preciso dizer algo aqui... Mas sobre o que devo falar?)",
  ui_story_5010_50100201_32_option_content = "Pergunte sobre a Guilda Lin",
  ui_story_5010_50100201_33_dialog_content = "Hum, Betel...? Você está familiarizado com o <color=#FFB400>Guilda Lin</color>?",
  ui_story_5010_50100201_34_dialog_content = "De nada.",
  ui_story_5010_50100201_35_option_content = "Pergunte sobre a represa",
  ui_story_5010_50100201_36_dialog_content = "Aquela represa que passamos no caminho pra cá era enorme! O povo de Umbraton o construiu sozinho?",
  ui_story_5010_50100201_37_dialog_content = "Foi construído a mando do Shadowlord para contornar quaisquer anomalias climáticas perigosas.",
  ui_story_5010_50100201_38_dialog_content = "Sob sua orientação, cada uma das principais guildas investiu no projeto, sendo o maior benfeitor o <color=#FFB400>Família Lin</color>.",
  ui_story_5010_50100201_39_dialog_content = "Então... A Guilda Lin...",
  ui_story_5010_50100201_40_dialog_content = "Sim? Você está interessado neles?",
  ui_story_5010_50100201_41_dialog_content = "Eu só ouvi algumas coisas aqui e ali sobre eles. Afinal, eles sempre foram muito... evasivos.",
  ui_story_5010_50100201_42_dialog_content = "Eles são especializados em produtos artesanais. Sua porcelana é de altíssima qualidade, assim como seus leques dobráveis.",
  ui_story_5010_50100201_43_dialog_content = "Você talvez esteja interessado em fazer negócios com a Família Lin?",
  ui_story_5010_50100201_44_dialog_content = "N-Não, não é isso... Eles me ajudaram com algo muito importante no passado, então eu queria parar e dizer olá.",
  ui_story_5010_50100201_45_dialog_content = "Eu vejo. O Lin Guild Hall está a caminho de nossa sede...",
  ui_story_5010_50100201_46_dialog_content = "Excelente! Ah, certo... Que tipo de papelada precisa ser cuidada na sede?",
  ui_story_5010_50100201_47_dialog_content = "É bem simples, na verdade. Você terá todo o tempo do mundo para examinar todos os livros contábeis e ativos também. Por favor, fique tranquilo.",
  ui_story_5010_50100201_48_dialog_content = "OK. Só espero que não seja muito longe...",
  ui_story_5010_50100201_49_dialog_content = "Estaremos aí em breve, garanto-vos...",
  ui_story_5010_50100201_50_dialog_content = "Esperar. Frankel sente que algo está errado.",
  ui_story_5010_50100201_51_dialog_content = "Frankel?",
  ui_story_5010_50100201_52_dialog_content = "Meu conhecido.",
  ui_story_5010_50100201_53_dialog_content = "Eles parecem ter sentido um cheiro desagradável... Um cheiro familiar.",
  ui_story_5010_50100201_54_dialog_content = "Eu também posso senti-los... Eclipsites!!",
  ui_story_5010_50100201_55_dialog_content = "Uau! Woof!",
  ui_story_5010_50100201_56_dialog_content = "Cuidado, Betel!",
  ui_story_5010_50100201_57_dialog_content = "Eu posso senti-los... Os Eclipsites estão se aproximando de nossa posição, e rápido!",
  ui_story_5010_50100201_58_dialog_content = "Você pode perceber seus movimentos tão claramente? Este deve ser o poder dos celestitas!",
  ui_story_5010_50100201_59_dialog_content = "Tenha certeza...",
  ui_story_5010_50100201_60_dialog_content = "Vou erradicar cada um deles.",
  ui_story_5010_50100202_1_dialog_content = "Não parecia que eles estavam apenas vagando por aí. Em vez de...",
  ui_story_5010_50100202_2_dialog_content = "Era quase como se estivessem indo direto para o alvo.",
  ui_story_5010_50100202_3_dialog_content = "Por alvo, quero dizer que é você, não é, PlayerName?",
  ui_story_5010_50100202_4_dialog_content = "Eu...",
  ui_story_5010_50100202_5_dialog_content = "Espere... Tem mais deles!",
  ui_story_5010_50100202_6_dialog_content = "Grrrrr!!",
  ui_story_5010_50100202_7_dialog_content = "Vou pegar os da frente! Fique atrás de mim por enquanto!",
  ui_story_5010_50100202_8_dialog_content = "Atenção!",
  ui_story_5010_50100202_9_dialog_content = "Graa—",
  ui_story_5010_50100202_10_dialog_content = "O que é isso? Você ainda está de pé depois de tudo isso? Você é um pouco diferente do que dizem os rumores, Celestita.",
  ui_story_5010_50100202_11_dialog_content = "... V-Você esteve nos seguindo esse tempo todo?",
  ui_story_5010_50100202_12_dialog_content = "Um membro do <color=#FFB400>Mercenários da Chama Branca</color>? Então... Você até contratou um guarda-costas.",
  ui_story_5010_50100202_13_dialog_content = "Para esconder sua presença tão bem todo esse tempo... Estou grato por você não ser nosso inimigo.",
  ui_story_5010_50100202_14_dialog_content = "Eu estou <color=#FFB400>Lucas</color>, dos Mercenários da Chama Branca. Recebi um pedido de Naroxel para protegê-lo, PlayerName.",
  ui_story_5010_50100202_15_dialog_content = "Me proteja?",
  ui_story_5010_50100202_16_dialog_content = "Isso mesmo! Naroxel diz que você é um bom amigo dela e que a ajudou no passado.",
  ui_story_5010_50100202_17_dialog_content = "... PlayerName, também solicitei que Luke, um velho amigo meu, viesse em seu auxílio...",
  ui_story_5010_50100202_18_dialog_content = "Mas Umbraton não é uma zona de guerra! Por que eu precisaria de proteção?",
  ui_story_5010_50100202_19_dialog_content = "Ei, eu sou apenas um mercenário. Eu nunca faço perguntas.",
  ui_story_5010_50100202_20_dialog_content = "Aham…",
  ui_story_5010_50100202_21_dialog_content = "Ah! Bom dia, Senhora Bethel da Guilda. Tal proeza de combate é de se esperar do sucessor de Lord Istvan, afinal!",
  ui_story_5010_50100202_22_dialog_content = "Hunf...",
  ui_story_5010_50100202_23_dialog_content = "Espere... Lucas. Você sabe alguma coisa sobre leilões clandestinos?",
  ui_story_5010_50100202_24_dialog_content = "Não muito, mas sempre posso reunir algumas informações para você, se quiser.",
  ui_story_5010_50100202_25_dialog_content = "Sério? Seria ótimo! Veja, eu quero ir ao leilão para descobrir se...",
  ui_story_5010_50100202_26_dialog_content = "PlayerName, acredito que devemos primeiro retornar à sede para atender nossa primeira ordem do dia!",
  ui_story_5010_50100202_27_dialog_content = "Você vai continuar nos escoltando pela retaguarda, Luke? Acredito que não há razão para se manter escondido agora.",
  ui_story_5010_50100202_28_dialog_content = "Ei, desculpe. Apenas um velho hábito na minha linha de trabalho...",
  ui_story_5010_50100202_29_dialog_content = "Derrubamos o dirigível do céu!",
  ui_story_5010_50100202_30_dialog_content = "Bom! Continue a busca! Certifique-se de que os mortos estão mortos e traga o resto para mim!",
  ui_story_5010_50100202_31_dialog_content = "Reno...",
  ui_story_5010_50100202_32_dialog_content = "Hum?",
  ui_story_5010_50100202_33_dialog_content = "Como vão as coisas?",
  ui_story_5010_50100202_34_dialog_content = "Tudo de acordo com o plano.",
  ui_story_5010_50100301_1_dialog_content = "Uau, os edifícios em Umbraton são muito distintos!",
  ui_story_5010_50100301_2_dialog_content = "Mas de alguma forma parece muito mais abafado na cidade.",
  ui_story_5010_50100301_3_dialog_content = "Que chato... Disseram que ia chover, mas não pegamos nem uma gota esse tempo todo.",
  ui_story_5010_50100301_4_dialog_content = "Ai...!",
  ui_story_5010_50100301_5_dialog_content = "Olhe olhe! Um novo torneio está prestes a começar!",
  ui_story_5010_50100301_6_dialog_content = "Huh? Um panfleto...?",
  ui_story_5010_50100301_7_dialog_content = "Deixe-me ver... Ah, é para a Underground Arena.",
  ui_story_5010_50100301_8_dialog_content = "Arena Subterrânea...?",
  ui_story_5010_50100301_9_dialog_content = "São jogos privados, por isso são considerados clandestinos. Mais ou menos como aquele leilão que você mencionou anteriormente.",
  ui_story_5010_50100301_10_dialog_content = "As regras para essas lutas indescritíveis são simples. Vença seu oponente usando todos os meios necessários e você vencerá.",
  ui_story_5010_50100301_11_dialog_content = "E se acontecer de você matar seu oponente... Você não é responsável por nada.",
  ui_story_5010_50100301_12_dialog_content = "Uau... Mas parece tão brutal. Quão...",
  ui_story_5010_50100301_13_dialog_content = "Bem, é verdade que essas lutas são completamente ilegais... Mas isso ainda é Umbraton.",
  ui_story_5010_50100301_14_dialog_content = "Então... todos estão dispostos a arriscar suas vidas pelas recompensas?",
  ui_story_5010_50100301_15_dialog_content = "Não exatamente, não. Para lutadores de verdade, essas lutas clandestinas são o campo de treinamento perfeito...",
  ui_story_5010_50100301_16_dialog_content = "Esse edifício é o Lin Guild Hall, PlayerName.",
  ui_story_5010_50100301_17_dialog_content = "Esta é uma de suas lojas? Parece especial, com certeza.",
  ui_story_5010_50100301_18_dialog_content = "De fato. Muito parecido com seus produtos, é uma prova de sua habilidade artesanal requintada.",
  ui_story_5010_50100301_19_dialog_content = "Há apenas um guarda postado na entrada, bem como um aviso que diz que a loja está fechada hoje.",
  ui_story_5010_50100301_20_dialog_content = "Ah... que pena... Parece que vou ter que esperar até a próxima vez para vê-los.",
  ui_story_5010_50100301_21_dialog_content = "Agora então, se não houver mais nada, por favor, siga-me até nossa sede, PlayerName.",
  ui_story_5010_50100301_22_dialog_content = "... Tá bem.",
  ui_story_5010_50100301_23_dialog_content = "Ah... Parece que a Verdade me trouxe até você hoje, Luke.",
  ui_story_5010_50100301_24_dialog_content = "Ah, você... Acho que deu tudo certo, então?",
  ui_story_5010_50100301_25_dialog_content = "Naturalmente...",
  ui_story_5010_50100301_26_dialog_content = "E-espere, vocês dois se conhecem?",
  ui_story_5010_50100301_27_dialog_content = "Há quanto tempo, PlayerName. Eu diria que nosso encontro é uma benção da Verdade...",
  ui_story_5010_50100301_28_dialog_content = "Mas Umbraton nunca foi um lugar tão simples. Eu oro para que você esteja alerta para os perigos ao redor... Tanto visíveis quanto invisíveis.",
  ui_story_5010_50100301_29_dialog_content = "Você pararia de falar em enigmas? Como eu poderia estar alerta para coisas que não posso ver em primeiro lugar?",
  ui_story_5010_50100301_30_dialog_content = "Não se preocupe com isso. Você me tem ao seu lado, assim como Betel.",
  ui_story_5010_50100301_31_dialog_content = "De fato. Eu garanto que você estará perfeitamente seguro em Umbraton sob minha vigilância, PlayerName.",
  ui_story_5010_50100301_32_dialog_content = "Ah sim, ouvir isso me acalma.",
  ui_story_5010_50100301_33_dialog_content = "Até nos encontrarmos na próxima vez, PlayerName.",
  ui_story_5010_50100301_34_dialog_content = "O que Faust lhe deu, Luke?",
  ui_story_5010_50100301_35_dialog_content = "Hmm... Uma surpresa, pode-se dizer. Você descobrirá em breve.",
  ui_story_5010_50100301_36_dialog_content = "... Espero que vocês dois estejam se divertindo com isso.",
  ui_story_5010_50100301_37_dialog_content = "Finalmente chegamos. Bem-vindo à Sede da Guilda Umbraton.",
  ui_story_5010_50100301_38_dialog_content = "Isso não parece nada com uma guilda... Parece uma fortaleza! Não é à toa que Luke diz que as pessoas evitam criar problemas por aqui...",
  ui_story_5010_50100301_39_dialog_content = "Senhora Betel.",
  ui_story_5010_50100301_40_dialog_content = "Bom dia. Alguma palavra do Shadowlord?",
  ui_story_5010_50100301_41_dialog_content = "Ainda não, minha senhora.",
  ui_story_5010_50100301_42_dialog_content = "Irei trazer os materiais necessários. Por favor espere um momento.",
  ui_story_5010_50100301_43_dialog_content = "Como quiser, minha senhora. Esse caminho por favor.",
  ui_story_5010_50100301_44_dialog_content = "(E-Todo mundo é tão cortês por aqui! Como devo reagir?)",
  ui_story_5010_50100301_45_dialog_content = "... Você não precisa se curvar, PlayerName.",
  ui_story_5010_50100301_46_dialog_content = "Este lugar me deixa nervoso.",
  ui_story_5010_50100301_47_dialog_content = "Vou esperar por você lá fora.",
  ui_story_5010_50100301_48_dialog_content = "Minhas desculpas pela espera, PlayerName. Aqui está o livro de ativos, bem como a documentação relevante. Por favor, leia-os pelo tempo que desejar.",
  ui_story_5010_50100301_49_dialog_content = "Onde Lucas foi?",
  ui_story_5010_50100301_50_dialog_content = "Ele acabou de sair alguns segundos atrás... Uau! É muita papelada!",
  ui_story_5010_50100301_51_dialog_content = "Me desculpe. O processo é um pouco complicado. Farei o possível para simplificá-lo, mas alguns lugares ainda exigirão sua assinatura.",
  ui_story_5010_50100301_52_dialog_content = "Aqui, por exemplo. E aqui. E aqui...",
  ui_story_5010_50100301_53_dialog_content = "Você precisa que eu explique alguma coisa disso?",
  ui_story_5010_50100301_54_dialog_content = "G-Graaah...!",
  ui_story_5010_50100301_55_dialog_content = "Ahh! HH-Ele acabou de se transformar em um...",
  ui_story_5010_50100301_56_dialog_content = "PlayerName! Tem um Eclipsite na entrada principal!",
  ui_story_5010_50100301_57_dialog_content = "?!",
  ui_story_5010_50100301_58_dialog_content = "Como um Eclipsite apareceu de repente aqui?!",
  ui_story_5010_50100301_59_dialog_content = "Evacuar os civis é nossa prioridade! Feche o portão principal e escolte todos para fora!",
  ui_story_5010_50100301_60_dialog_content = "Entendido!",
  ui_story_5010_50100301_61_dialog_content = "Você tem muita coragem... Causando problemas na frente da Guilda!",
  ui_story_5010_50100301_62_dialog_content = "Tem mais!",
  ui_story_5010_50100301_63_dialog_content = "Lute, Frankel!",
  ui_story_5010_50100301_64_dialog_content = "Fique atrás de mim, PlayerName!",
  ui_story_5010_50100401_1_dialog_content = "Senhora Betel!",
  ui_story_5010_50100401_2_dialog_content = "Você está... Oh, graças a Deus você está bem, minha senhora!",
  ui_story_5010_50100401_3_dialog_content = "Onde estão os guardas? Por que há tão poucas pessoas aqui?",
  ui_story_5010_50100401_4_dialog_content = "D-Não se preocupe, Lady Bethel! Eu vou encontrar mais ajuda! Deixe isso comigo!",
  ui_story_5010_50100401_5_dialog_content = "Aqueles eram seus homens, Betel?",
  ui_story_5010_50100401_6_dialog_content = "Sim, e daí?",
  ui_story_5010_50100401_7_dialog_content = "Essas pessoas não parecem ter nenhuma experiência de combate. Basta olhar para eles, eles estão todos morrendo de medo.",
  ui_story_5010_50100401_8_dialog_content = "Hunf...",
  ui_story_5010_50100401_9_dialog_content = "Espere!",
  ui_story_5010_50100401_10_dialog_content = "Descobriu alguma coisa?",
  ui_story_5010_50100401_11_dialog_content = "Aquele canto! Algo está lá!",
  ui_story_5010_50100401_12_dialog_content = "... Frankel, vá ver o que está por vir.",
  ui_story_5010_50100401_13_dialog_content = "Uau!",
  ui_story_5010_50100401_14_dialog_content = "Graagh!",
  ui_story_5010_50100401_15_dialog_content = "Uau! Woof!",
  ui_story_5010_50100401_16_dialog_content = "Isso foi rápido, não é?",
  ui_story_5010_50100401_17_dialog_content = "Graaaaaah!!",
  ui_story_5010_50100401_18_dialog_content = "Simples de pensar, tudo a mesma coisa. Mandar Frankel à frente foi o suficiente para prolongar a situação.",
  ui_story_5010_50100401_19_dialog_content = "Obrigado pelo aviso, PlayerName. Você é muito perspicaz.",
  ui_story_5010_50100401_20_dialog_content = "Tem certeza que isso é uma emboscada? Eu ainda sinto muitos deles por perto! Fique em guarda...",
  ui_story_5010_50100401_21_dialog_content = "Aceite sua punição!",
  ui_story_5010_50100401_22_dialog_content = "Graaaaugh...!",
  ui_story_5010_50100401_23_dialog_content = "<color=#FFB400>Pittman</color>!",
  ui_story_5010_50100401_24_dialog_content = "Lumopolis... Por que eles acharam por bem enviar alguém do Tribunal de Justiça para cá?",
  ui_story_5010_50100401_25_dialog_content = "O cheiro desta criatura... Graças a ele, finalmente consegui encontrar este lugar.",
  ui_story_5010_50100401_26_dialog_content = "Esse é Wayne Pittman, um investigador do Hall of Justice. Uma vez lutamos lado a lado, Betel.",
  ui_story_5010_50100401_27_dialog_content = "Saudações, Sr. Pittman de Lumopolis. Eu sou Bethel, o chefe da Guilda Umbraton.",
  ui_story_5010_50100401_28_dialog_content = "Você estava procurando por algo aqui em Umbraton? Se você está procurando a estrada de volta para Lumopolis, ficarei feliz em mostrar a você.",
  ui_story_5010_50100401_29_dialog_content = "... Fique tranquilo, não estou aqui com má intenção. Minha investigação atual não tem nada a ver com nenhum de vocês.",
  ui_story_5010_50100401_30_dialog_content = "Os Eclipsites agora há pouco... Algum de vocês viu exatamente como eles apareceram aqui?",
  ui_story_5010_50100401_31_dialog_content = "Foi muito repentino e os guardas não conseguiram responder a tempo. Esses Eclipsites eram mais poderosos do que o normal e pareciam bastante familiarizados com o quartel-general.",
  ui_story_5010_50100401_32_dialog_content = "Eu estava do lado de fora. Na verdade, eu vi uma pessoa comum de repente se transformando em uma...",
  ui_story_5010_50100401_33_dialog_content = "Hmm... Exatamente como eu pensei.",
  ui_story_5010_50100401_34_dialog_content = "<color=#FFB400>Melhoradores</color>.",
  ui_story_5010_50100401_35_dialog_content = "Me desculpe, En-o quê?",
  ui_story_5010_50100401_36_dialog_content = "Quando esses Eclipsites apareceram, algum deles exibiu comportamento estranho ou errático?",
  ui_story_5010_50100401_37_dialog_content = "Eu realmente não vi nada. E você, Betel?",
  ui_story_5010_50100401_38_dialog_content = "Em um momento, Frankel detectou algo...",
  ui_story_5010_50100401_39_dialog_content = "Graaaaaaagh!!",
  ui_story_5010_50100401_40_dialog_content = "Uma pena... Só perdi mais uma chance de vê-lo usar o intensificador.",
  ui_story_5010_50100401_41_dialog_content = "Talvez se o abrirmos, ainda possamos descobrir algo?",
  ui_story_5010_50100401_42_dialog_content = "Você não vai ajudar, Luke?",
  ui_story_5010_50100401_43_dialog_content = "Meu trabalho é protegê-lo, não ajudar um oficial de Lumopolis ou travar suas batalhas.",
  ui_story_5010_50100402_1_dialog_content = "Obrigado pela sua ajuda, Sr. Pittman.",
  ui_story_5010_50100402_2_dialog_content = "Mas como exatamente eles fizeram isso? Como a velocidade e o poder deles podem aumentar de repente?",
  ui_story_5010_50100402_3_dialog_content = "O que chamamos de intensificador. É uma droga poderosa que concede aos aurorianos o poder de um Eclipsite, mesmo que apenas por um curto período de tempo.",
  ui_story_5010_50100402_4_dialog_content = "Mais preocupante, no entanto, é que aqueles que ingerem esses intensificadores se transformarão em Eclipsites.",
  ui_story_5010_50100402_5_dialog_content = "Não é de admirar que aqueles que esperavam para nos emboscar não pudessem se conter quando Frankel passou... Acho que eles não têm muito tempo para paciência.",
  ui_story_5010_50100402_6_dialog_content = "Isso significa que, se tivéssemos passado por eles... Estaríamos em apuros.",
  ui_story_5010_50100402_7_dialog_content = "Ufa, isso foi por pouco... Estou de volta, Lady Bethel! Parece que os Eclipsitas foram praticamente exterminados...",
  ui_story_5010_50100402_8_dialog_content = "Senhora Betel! Estava aqui!",
  ui_story_5010_50100402_9_dialog_content = "Guardem este lugar, todos vocês! Set!",
  ui_story_5010_50100402_10_dialog_content = "Sim, minha senhora!",
  ui_story_5010_50100402_11_dialog_content = "Vá até o Shadowlord e peça mais guardas!",
  ui_story_5010_50100402_12_dialog_content = "Entendido!",
  ui_story_5010_50100402_13_dialog_content = "O uso de um aprimorador para transformar e aumentar temporariamente o poder de combate de alguém... Isso soa familiar para você, PlayerName?",
  ui_story_5010_50100402_14_dialog_content = "Será que...?",
  ui_story_5010_50100402_15_dialog_content = "Isso é. Desde o dia em que nos separamos em Eraveil, venho investigando essas transformações...",
  ui_story_5010_50100402_16_dialog_content = "E finalmente, minha investigação me trouxe aqui, para Umbraton...",
  ui_story_5010_50100402_17_dialog_content = "Do jeito que está, os efeitos desse intensificador são surpreendentemente semelhantes à modificação grotesca que vimos antes. Portanto, é provável que eles compartilhem uma origem.",
  ui_story_5010_50100402_18_dialog_content = "A origem dessas artes sombrias e distorcidas poderia estar em Umbraton?",
  ui_story_5010_50100402_19_dialog_content = "Não acho que esse intensificador seja de Umbraton, Sr. Pittman. Estou no comando da Guilda Umbraton e nunca ouvi falar dela!",
  ui_story_5010_50100402_20_dialog_content = "Concordou. Eu não ouvi mais do que um sussurro sobre algo assim.",
  ui_story_5010_50100402_21_dialog_content = "Além disso, ataques de Eclipsite não são exatamente incomuns por aqui. Este é Umbraton, não um paraíso confortável no céu.",
  ui_story_5010_50100402_22_dialog_content = "De qualquer forma, agradeço que você esteja ileso, PlayerName. Eu nunca poderia explicar isso ao Shadowlord se algo acontecesse com você.",
  ui_story_5010_50100402_23_dialog_content = "Shadowlord... Shadowlord... Sim, isso me lembra.",
  ui_story_5010_50100402_24_dialog_content = "Do que você está falando agora, Pittman?",
  ui_story_5010_50100402_25_dialog_content = "Se alguém entende completamente os acontecimentos em Umbraton, é o próprio Shadowlord. Eu preciso vê-lo.",
  ui_story_5010_50100402_26_dialog_content = "Irei apresentar meu relatório ao Sr. Istvan e aguardarei suas ordens.",
  ui_story_5010_50100402_27_dialog_content = "O que o faz ter tanta certeza de que Umbraton é a fonte do seu problema, Pittman?",
  ui_story_5010_50100402_28_dialog_content = "Você precisa se acalmar, Luke... Ele também tem seu próprio trabalho a fazer...",
  ui_story_5010_50100402_29_dialog_content = "Vamos esclarecer as coisas em vez de brigar aqui.",
  ui_story_5010_50100402_30_dialog_content = "Temos inimigos que podem se transformar em Eclipsites agora, mas seus números e motivos ainda são desconhecidos.",
  ui_story_5010_50100402_31_dialog_content = "Dadas as nossas circunstâncias atuais, PlayerName... Acredito que devemos adiar nossos negócios anteriores para uma data posterior. Isso é aceitável?",
  ui_story_5010_50100402_32_dialog_content = "Para ser honesto, provavelmente seria muito mais fácil deixá-los aqui do que carregá-los para todo lado.",
  ui_story_5010_50100402_33_dialog_content = "Concordou. Vou dar uma passada na delegacia para ver se algum estranho apareceu na cidade ultimamente.",
  ui_story_5010_50100402_34_dialog_content = "A estação?",
  ui_story_5010_50100402_35_dialog_content = "É o lugar certo para obter informações por aqui.",
  ui_story_5010_50100402_36_dialog_content = "Também não acho que seja muito longe daqui... Por que não vem comigo, PlayerName? Eu não posso deixar você sozinho, de qualquer maneira.",
  ui_story_5010_50100402_37_dialog_content = "Com licença, posso perguntar sobre os intensificadores em sua estação?",
  ui_story_5010_50100402_38_dialog_content = "Talvez, mas não posso dizer com certeza. Não custa nada tentar a sorte, no entanto.",
  ui_story_5010_50100402_39_dialog_content = "Há um cruzamento no centro da cidade, onde penduram luzes azuis nas ruas. O lugar para onde vamos é um bar na esquina da rua, convenientemente chamado de The Crossroads.",
  ui_story_5010_50100402_40_dialog_content = "Que apropriado...",
  ui_story_5010_50100402_41_dialog_content = "O bar recebe todos os tipos de pessoas, então certifique-se de estar pronto antes de entrarmos.",
  ui_story_5010_50100402_42_dialog_content = "Duvido que possam ser piores do que os Eclipsites aprimorados contra os quais lutamos hoje.",
  ui_story_5010_50100402_43_dialog_content = "Só queremos saber quem está distribuindo esses intensificadores. Eu não acho que haja Eclipsites em um bar.",
  ui_story_5010_50100402_44_dialog_content = "eu vou proteger PlayerName. Sinta-se à vontade para investigar, Sr. Pittman... por conta própria.",
  ui_story_5010_50100402_45_dialog_content = "Um cruzamento com luzes azuis... Estranho, não me lembro de ter notado um lugar assim antes?",
  ui_story_5010_50100402_46_dialog_content = "Só existe há alguns anos. Talvez você ainda estivesse estudando no exterior quando abriu?",
  ui_story_5010_50100402_47_dialog_content = "Podemos ir juntos, então. Talvez aprendamos mais sobre quem lançou um ataque à Guilda.",
  ui_story_5010_50100402_48_dialog_content = "Er... Tudo bem, faça do seu jeito, Srta. Bethel. Mas, por favor, assim que chegarmos...",
  ui_story_5010_50100402_49_dialog_content = "Cuidado com o que você fala e faz aí dentro.",
  ui_story_5010_50100501_1_dialog_content = "A Encruzilhada pode ser um lugar complicado, então é do interesse de todos tomar cuidado com suas palavras.",
  ui_story_5010_50100501_2_dialog_content = "Sem problema.",
  ui_story_5010_50100501_3_dialog_content = "Está completamente silencioso por aqui... Será que está aberto?",
  ui_story_5010_50100501_4_dialog_content = "A luz azul está acesa, então deveria estar. É estranho, porém... Normalmente, você pode ouvir o tumulto a pelo menos três quarteirões de distância...",
  ui_story_5010_50100501_5_dialog_content = "De qualquer forma, fique atento quando estivermos lá dentro.",
  ui_story_5010_50100501_6_dialog_content = "A porta está, de fato, aberta...",
  ui_story_5010_50100501_X6_dialog_content = "Com licença!",
  ui_story_5010_50100501_7_dialog_content = "Bethel, você deveria pedir no bar...",
  ui_story_5010_50100501_8_dialog_content = "...",
  ui_story_5010_50100501_9_dialog_content = "O que você está olhando?!",
  ui_story_5010_50100501_10_dialog_content = "Nossa!",
  ui_story_5010_50100501_11_dialog_content = "PlayerName! Venha pra cá!",
  ui_story_5010_50100501_12_dialog_content = "Você, uh... Pode querer manter distância deles. Me espera aqui, ok?",
  ui_story_5010_50100501_13_dialog_content = "Ok... Você é o chefe.",
  ui_story_5010_50100501_14_dialog_content = "Boa noite.",
  ui_story_5010_50100501_15_dialog_content = "...",
  ui_story_5010_50100501_16_dialog_content = "Eu sou Pittman, um investigador de Lumopolis.",
  ui_story_5010_50100501_17_dialog_content = "Eu gostaria de fazer algumas perguntas a todos vocês. Sua cooperação é muito apreciada.",
  ui_story_5010_50100501_18_dialog_content = "?!?!",
  ui_story_5010_50100501_19_dialog_content = "W-Wayne! Você não pode simplesmente perguntar do nada assim!!",
  ui_story_5010_50100501_20_dialog_content = "...",
  ui_story_5010_50100501_21_dialog_content = "...",
  ui_story_5010_50100501_22_dialog_content = "Uau! Quando eles chegaram tão perto de nós?!",
  ui_story_5010_50100501_23_dialog_content = "O que você pensa que está fazendo? Voltam, PlayerName!",
  ui_story_5010_50100501_24_dialog_content = "Do que você tem medo, garoto? Não é como se eu fosse te comer.",
  ui_story_5010_50100501_25_dialog_content = "Nosso chefe quer falar com vocês dois. Sente-se com ele, sim?",
  ui_story_5010_50100501_26_dialog_content = "...",
  ui_story_5010_50100501_27_dialog_content = "...",
  ui_story_5010_50100501_28_dialog_content = "Há quanto tempo, Sr. Rhein.",
  ui_story_5010_50100501_29_dialog_content = "Lady Bethel... Um dia lento no trabalho, presumo?",
  ui_story_5010_50100501_30_dialog_content = "Não há trabalho a ser feito hoje, não com o incidente que aconteceu na sede mais cedo. Como por você...",
  ui_story_5010_50100501_31_dialog_content = "Como foram os negócios para o <color=#FFB400>Guilda Leão Azul</color> recentemente?",
  ui_story_5010_50100501_32_dialog_content = "Hahaha, é uma vida, você sabe! Nada mais!",
  ui_story_5010_50100501_33_dialog_content = "Não há necessidade de ser tão tenso! Estamos apenas conversando, só isso!",
  ui_story_5010_50100501_34_dialog_content = "Então vamos começar. Sobre o que exatamente você deseja conversar?",
  ui_story_5010_50100501_35_dialog_content = "Será sobre os aprimoradores ou o ataque à nossa Guilda hoje cedo?",
  ui_story_5010_50100501_36_dialog_content = "Não tenho interesse em conversar sobre mais nada.",
  ui_story_5010_50100501_37_dialog_content = "O que é isso? Uma conversa com o chefe da Blue Lion Guild, e eu não fui convidado? Achei que estamos juntos aqui, sabe?",
  ui_story_5010_50100501_38_dialog_content = "Um mercenário da Chama Branca, um investigador do Hall da Justiça, o chefe da Guilda Umbraton e...",
  ui_story_5010_50100501_39_dialog_content = "... Um nanico indefeso que não pode usar nenhuma forma de Luminatics.",
  ui_story_5010_50100501_40_dialog_content = "Você tem aqui uma equipe bastante heterogênea, Lady Bethel.",
  ui_story_5010_50100501_41_dialog_content = "Não nos impediu de acabar com uma legião de Eclipsites antes, você sabe...",
  ui_story_5010_50100501_42_dialog_content = "De fato.",
  ui_story_5010_50100501_43_dialog_content = "Desculpe, mas não estava falando com você, Luke. O chefe de uma extinta gangue de cães mercenários ainda é apenas um cachorro, então por que você não mastiga um osso e deixa a conversa conosco?",
  ui_story_5010_50100501_44_dialog_content = "!!",
  ui_story_5010_50100501_45_dialog_content = "Rhein.",
  ui_story_5010_50100501_46_dialog_content = "Estamos aqui para obter informações, não para lutar. Se você não tem nada para dar, acredito que há muitas pessoas com quem podemos conversar.",
  ui_story_5010_50100501_47_dialog_content = "Eu não. Não ouvi nada a noite toda.",
  ui_story_5010_50100501_48_dialog_content = "Nesse caso, este papo termina aqui.",
  ui_story_5010_50100501_49_dialog_content = "Vamos, Betel.",
  ui_story_5010_50100501_50_dialog_content = "...",
  ui_story_5010_50100501_51_dialog_content = "Ufa, isso foi intenso. Ele simplesmente ignorou um investigador de Lumopolis... Eles realmente não têm medo da lei, têm?",
  ui_story_5010_50100501_52_dialog_content = "Bem, a Guilda do Leão Azul é realmente poderosa. Eles acumularam dinheiro e mão de obra em excesso ultimamente...",
  ui_story_5010_50100501_53_dialog_content = "Mas seus negócios nunca teriam prosperado sem a Sede da Guilda. Afinal, todas as rotas comerciais estão sob nosso controle.",
  ui_story_5010_50100501_54_dialog_content = "...",
  ui_story_5010_50100501_55_dialog_content = "Tudo bem, Lucas?",
  ui_story_5010_50100501_56_dialog_content = "Rhein nunca gostou muito de nós, mercenários, mas a Guilda do Leão Azul é muito poderosa agora... Não podemos realmente fazer nada com ele.",
  ui_story_5010_50100501_57_dialog_content = "Ouvi dizer que ele abriu algumas rotas comerciais não oficiais para si mesmo, e eles estão arrecadando os lucros.",
  ui_story_5010_50100501_58_dialog_content = "Quanto ao que exatamente está sendo vendido, não houve nenhum relatório para a Sede da Guilda sobre isso...",
  ui_story_5010_50100501_59_dialog_content = "O quê?",
  ui_story_5010_50100501_60_dialog_content = "Parece que uma investigação adequada sobre a Blue Lion Guild está em ordem.",
  ui_story_5010_50100501_61_dialog_content = "!!",
  ui_story_5010_50100501_62_dialog_content = "Set? Qual é o problema?",
  ui_story_5010_50100501_63_dialog_content = "Shadow... Agora mesmo... Encontrei-o!",
  ui_story_5010_50100501_64_dialog_content = "O que você está tentando dizer? Componha-se!",
  ui_story_5010_50100501_65_dialog_content = "O Senhor das Sombras! Ele... Ele foi atacado...!",
  ui_story_5010_50100501_66_dialog_content = "...",
  ui_story_5010_50100501_67_dialog_content = "!!!",
  ui_story_5010_50100501_68_dialog_content = "Betel? O que está acontecendo?",
  ui_story_5010_50100501_69_dialog_content = "Uau! Uau, au!!",
  ui_story_5010_50100501_70_dialog_content = "Espera... Quem é aquele à frente?",
  ui_story_5010_50100501_71_dialog_content = "Cuidado, PlayerName!!",
  ui_story_5010_50100501_72_dialog_content = "Bwahahahaha!",
  ui_story_5010_50100501_73_dialog_content = "Aquele cheiro familiar de novo...",
  ui_story_5010_50100501_74_dialog_content = "Que <color=#FFB400>comprimido</color>... Não me diga...!",
  ui_story_5010_50100501_75_dialog_content = "Isso... Isso mesmo! Graaaah!",
  ui_story_5010_50100501_76_dialog_content = "Ele... Ele virou um Eclipsite!!!",
  ui_story_5010_50100501_77_dialog_content = "Bethel!",
  ui_story_5010_50100501_78_dialog_content = "Não consigo alcançar o Shadowlord! Ele provavelmente está sob ataque também!",
  ui_story_5010_50100501_79_dialog_content = "O inimigo está atacando! Prepare-se para a batalha! ... Betel, está me ouvindo?!",
  ui_story_5010_50100501_80_dialog_content = "... Dra. Também não consigo falar com Seth.",
  ui_story_5010_50100501_81_dialog_content = "Você e eu vamos segurá-los, Wayne!",
  ui_story_5010_50100501_82_dialog_content = "Tente capturar um vivo, isso é possível?",
  ui_story_5010_50100502_1_dialog_content = "Esses Eclipsitas... Não, são pessoas de Umbraton que se parecem com os Eclipsitas. É isso que a pílula faz...?",
  ui_story_5010_50100502_2_dialog_content = "Vocês todos viram claramente a transformação? Eles se transformam em criaturas mais poderosas que os Eclipsites comuns.",
  ui_story_5010_50100502_3_dialog_content = "É esta a modificação que você estava falando antes?",
  ui_story_5010_50100502_4_dialog_content = "A rigor, é uma espécie de modificação, sim.",
  ui_story_5010_50100502_5_dialog_content = "Tem certeza de que não sabe mais nada sobre esses intensificadores? Umbraton realmente nunca experimentou esse tipo de perigo no passado?",
  ui_story_5010_50100502_6_dialog_content = "Não que eu saiba, não. Este deve ser um desenvolvimento relativamente recente, ou então toda a cidade estaria em estado de pânico agora.",
  ui_story_5010_50100502_7_dialog_content = "Mesmo agora, ainda estou tendo problemas para acreditar. Para uma pessoa se transformar em um Eclipsite assim...",
  ui_story_5010_50100502_8_dialog_content = "Parece que a Blue Lion Guild está de alguma forma conectada a tudo isso.",
  ui_story_5010_50100502_9_dialog_content = "Sim, eu concordo. Isso não pode ser apenas uma coincidência.",
  ui_story_5010_50100502_10_dialog_content = "Infelizmente, não posso afirmar nada sobre as identidades dessas pessoas em seu estado transformado. Eles também não deixaram pistas...",
  ui_story_5010_50100502_11_dialog_content = "Vou continuar minha investigação aqui e seguir os movimentos de Rhein por enquanto.",
  ui_story_5010_50100502_12_dialog_content = "Ei... Onde fica Betel?",
  ui_story_5010_50100502_13_dialog_content = "Betel! Onde você esteve?",
  ui_story_5010_50100502_14_dialog_content = "A situação do Shadowlord ainda não está clara. Tudo o que sei é que ele foi atacado!",
  ui_story_5010_50100502_15_dialog_content = "Eu devo ir até ele.",
  ui_story_5010_50100502_16_dialog_content = "Você está bem?",
  ui_story_5010_50100502_17_dialog_content = "Por favor me perdoe, PlayerName... Teremos que adiar ainda mais a questão de sua herança. Discutiremos isso quando voltar.",
  ui_story_5010_50100502_18_dialog_content = "Desculpe.",
  ui_story_5010_50100502_19_dialog_content = "Shadowlord foi atacado? Poderia ser a Guilda do Leão Azul...?",
  ui_story_5010_50100502_20_dialog_content = "Não tenho certeza, mas cuidaremos de nossos próprios assuntos, obrigado.",
  ui_story_5010_50100502_21_dialog_content = "...",
  ui_story_5010_50100502_22_dialog_content = "Então, qual é o plano agora, PlayerName?",
  ui_story_5010_50100502_23_dialog_content = "Parece que não podemos fazer muito por nenhum deles agora.",
  ui_story_5010_50100502_24_dialog_content = "Oh, certo! Ainda tem o leilão clandestino!",
  ui_story_5010_50100502_25_dialog_content = "Sim, isso me lembra... O que exatamente você está procurando neste leilão?",
  ui_story_5010_50100502_26_dialog_content = "Um conjunto de componentes da sala de simulação. Naroxel me contou sobre eles.",
  ui_story_5010_50100502_27_dialog_content = "Eles são peças cruciais para um Colossus, e Soroz pode ser capaz de usá-los.",
  ui_story_5010_50100502_28_dialog_content = "Entendi. Nesse caso, faça exatamente o que eu disser quando chegarmos lá.",
  ui_story_5010_50100502_29_dialog_content = "Não podemos permitir que mais coisas dêem errado hoje!",
  ui_story_5010_50100601_1_dialog_content = "Estamos quase lá, PlayerName.",
  ui_story_5010_50100601_2_dialog_content = "Luke... O-O que devo fazer? Devo ir falar com o leiloeiro?",
  ui_story_5010_50100601_3_dialog_content = "De jeito nenhum! Cada participante desses leilões clandestinos é completamente anônimo. Você tem que passar pelo organizador para obter acesso.",
  ui_story_5010_50100601_4_dialog_content = "Veja, o vendedor dá seus itens para o organizador, e então os compradores e o organizador...",
  ui_story_5010_50100601_5_dialog_content = "Ah, entendi agora. A gente tem que ir até o organizador e fazer uma oferta, é isso?",
  ui_story_5010_50100601_6_dialog_content = "Como se fosse tão fácil! O organizador organizará um leilão anônimo em uma determinada data, e a venda vai para o maior lance.",
  ui_story_5010_50100601_7_dialog_content = "Em uma determinada data? Então temos que esperar o leilão acontecer...",
  ui_story_5010_50100601_8_dialog_content = "Não exatamente. Podemos procurar o organizador para obter alguns detalhes deles. Com alguma sorte, podemos até ver as mercadorias...",
  ui_story_5010_50100601_9_dialog_content = "Eu entendo. Aí é só aparecer no leilão e fazer uma oferta alta por eles, né?",
  ui_story_5010_50100601_10_dialog_content = "Como eu disse, PlayerName, os compradores desses leilões também devem manter o anonimato total... Portanto, se você quiser dar um lance em qualquer coisa, o processo é um pouco mais complicado do que isso.",
  ui_story_5010_50100601_11_dialog_content = "anonimato total? Mesmo para os compradores?",
  ui_story_5010_50100601_12_dialog_content = "É claro! Se você consegue comprar algo valioso e todo mundo sabe quem você é, você está basicamente pedindo para ser roubado.... Ou pior.",
  ui_story_5010_50100601_13_dialog_content = "De qualquer forma, levaria horas para explicar tudo. Seria melhor irmos dar uma olhada primeiro.",
  ui_story_5010_50100601_14_dialog_content = "Ok, Lucas.",
  ui_story_5010_50100601_15_dialog_content = "Aqui está uma lista de itens que serão vendidos em breve, bem como as datas dos leilões. Dê uma olhada, PlayerName.",
  ui_story_5010_50100601_16_dialog_content = "Essa pessoa agora...",
  ui_story_5010_50100601_17_dialog_content = "Isso não importa.",
  ui_story_5010_50100601_18_dialog_content = "Eles provavelmente não realizarão um leilão para os componentes da sala de simulação que você está procurando tão cedo. Talvez possamos tentar perguntar primeiro o preço inicial do vendedor.",
  ui_story_5010_50100601_19_dialog_content = "As coisas nesta lista... Como... Como alguém poderia sequer pensar em...",
  ui_story_5010_50100601_20_dialog_content = "Hahahaha! Há uma razão para este ser um leilão clandestino, você sabe!",
  ui_story_5010_50100601_21_dialog_content = "Como eles se deparam com esse tipo de coisa?",
  ui_story_5010_50100601_22_dialog_content = "Hmm... Isso é coisa do vendedor, ninguém sabe. Eles podem ter escavado, ou feito eles mesmos... Ou podem ter roubado.",
  ui_story_5010_50100601_23_dialog_content = "Espere ... Então ninguém se importa como eles descobriram essas coisas ?!",
  ui_story_5010_50100601_24_dialog_content = "Haha, o que você acha?",
  ui_story_5010_50100601_25_dialog_content = "E as pessoas não estão preocupadas em dar as coisas que têm secretamente aos organizadores do leilão?",
  ui_story_5010_50100601_26_dialog_content = "Bem, o leilão clandestino existe há anos. Eles têm algum grau de credibilidade, sabe?",
  ui_story_5010_50100601_27_dialog_content = "Está bem movimentado... Todas essas pessoas estão aqui para ver as mercadorias em leilão?",
  ui_story_5010_50100601_28_dialog_content = "Controle-se!",
  ui_story_5010_50100601_29_dialog_content = "A julgar pelo comportamento de todos, parece que eles estão aqui para dar lances no leilão de hoje.",
  ui_story_5010_50100601_30_dialog_content = "Há toneladas de pessoas aqui... muitos deles são os figurões de Umbraton.",
  ui_story_5010_50100601_31_dialog_content = "... Huh? Aquelas pessoas ali...",
  ui_story_5010_50100601_32_dialog_content = "Fausto? E Beryl? ... Até a Paloma também?!",
  ui_story_5010_50100601_33_dialog_content = "Uau... Fiquei surpreso ao descobrir que você conhecia Fausto, PlayerName...",
  ui_story_5010_50100601_34_dialog_content = "Mas eu nunca teria imaginado que você também conhecia aquelas senhoras da Verdadeira Ordem?",
  ui_story_5010_50100601_35_dialog_content = "É uma longa história, com certeza...",
  ui_story_5010_50100601_36_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_5010_50100601_37_dialog_content = "Está começando a chover...? Vamos, Luke, vamos entrar!",
  ui_story_5010_50100601_38_dialog_content = "Sim claro.",
  ui_story_5010_50100601_39_dialog_content = "Então, finalmente chove...",
  ui_story_5010_50100601_40_dialog_content = "...",
  ui_story_5010_50100601_41_dialog_content = "...",
  ui_story_5010_50100601_42_dialog_content = "...",
  ui_story_5010_50100601_43_dialog_content = "(Está tão quieto...)",
  ui_story_5010_50100601_44_dialog_content = "Deste jeito, PlayerName. É lá que acontecem os leilões. Estamos procurando o organizador, lembra?",
  ui_story_5010_50100601_45_dialog_content = "A propósito... Você será capaz de dizer se essas peças são falsas ou não, PlayerName?",
  ui_story_5010_50100601_46_dialog_content = "A organizadora conta que as peças foram avaliadas por técnicos tanto da Illumina quanto da Rediesel Wrench. Aqui está o certificado.",
  ui_story_5010_50100601_47_dialog_content = "Eh, sem brincadeira...",
  ui_story_5010_50100601_48_dialog_content = "Essas duas pessoas são minhas amigas, Luke. Estes devem ser o negócio real!",
  ui_story_5010_50100601_49_dialog_content = "Tudo bem, então parece que a próxima etapa é se registrar no leilão como compradores em potencial.",
  ui_story_5010_50100601_50_dialog_content = "Então, quanto você está disposto a gastar nessas peças, PlayerName?",
  ui_story_5010_50100601_51_dialog_content = "... <size=45>678 Nightium?!</size>",
  ui_story_5010_50100601_52_dialog_content = "Uh... B-Bem... Isso deve ser cerca de um milésimo do preço pedido pelo vendedor...",
  ui_story_5010_50100601_53_dialog_content = "M-Mas esse é todo o dinheiro que tenho comigo agora...",
  ui_story_5010_50100601_54_dialog_content = "Entendo... Parece que teremos que voltar e pensar em outra coisa.",
  ui_story_5010_50100601_55_dialog_content = "Felizmente, o leilão desses componentes ainda não vai começar.",
  ui_story_5010_50100601_56_dialog_content = "Direita...",
  ui_story_5010_50100601_57_dialog_content = "Eu não me preocuparia muito com isso. Se conseguirmos encontrar algo de alto valor, podemos negociar com o vendedor...",
  ui_story_5010_50100601_58_dialog_content = "<size=45><color=#e8d9bb>Bang!</color></size>",
  ui_story_5010_50100601_59_dialog_content = "Que barulho foi esse agora?",
  ui_story_5010_50100601_60_dialog_content = "Veio da sala de leilões... Tenho um mau pressentimento sobre isso.",
  ui_story_5010_50100601_61_dialog_content = "Vamos, vamos dar uma olhada!",
  ui_story_5010_50100601_62_dialog_content = "E-espere, senhor! Você não pode simplesmente...",
  ui_story_5010_50100601_63_dialog_content = "Não pode apenas o quê? Fazem isto?",
  ui_story_5010_50100601_64_dialog_content = "<size=45><color=#e8d9bb>Bang! Bang!</color></size>",
  ui_story_5010_50100601_65_dialog_content = "Tiros disparados?!",
  ui_story_5010_50100601_66_dialog_content = "Abaixe-se! Não se mexa...",
  ui_story_5010_50100601_67_dialog_content = "Desculpe interromper, pessoal...",
  ui_story_5010_50100601_68_dialog_content = "O que pensa que está fazendo?!",
  ui_story_5010_50100601_69_dialog_content = "Shh... Por favor, fique em silêncio, por favor.",
  ui_story_5010_50100601_70_dialog_content = "Viemos fazer um anúncio, nada mais. Não há motivo para pânico...",
  ui_story_5010_50100601_71_dialog_content = "Por favor, Maude, se me permite? Eu queria dizer essas palavras por... Oh, tanto tempo...",
  ui_story_5010_50100601_72_dialog_content = "Agora então... De hoje em diante, eu, Rhein, servirei como o novo Umbraton...",
  ui_story_5010_50100601_73_dialog_content = "<color=#FFB400>governante</color>.",
  ui_story_5010_50100601_74_dialog_content = "?!",
  ui_story_5010_50100601_75_dialog_content = "Aquele cara ao lado de Rhein é Maude, o líder de uma gangue local chamada Solus.",
  ui_story_5010_50100601_76_dialog_content = "Solus é uma das gangues mais poderosas aqui em Umbraton. Eu nunca teria imaginado que eles jogariam seu chapéu com o Blue Lion Guild.",
  ui_story_5010_50100601_77_dialog_content = "Rhein, Maude... O que vocês estão falando?!",
  ui_story_5010_50100601_78_dialog_content = "Não te perguntamos...",
  ui_story_5010_50100601_79_dialog_content = "Pra calar a boca!!",
  ui_story_5010_50100601_80_dialog_content = "Por que você tem que me fazer gritar como um plebeu humilde...",
  ui_story_5010_50100601_81_dialog_content = "Vamos tentar de novo... Atenção, pessoal! Uma grande revolução está prestes a começar, e serei eu quem conduzirá Umbraton a uma gloriosa nova era!",
  ui_story_5010_50100601_82_dialog_content = "É uma grande honra discutir o futuro de Umbraton com os estimados líderes da Guilda reunidos aqui hoje...",
  ui_story_5010_50100601_83_dialog_content = "Quanto ao Shadowlord, de quem tenho certeza que todos estão cochichando, posso garantir a todos que ele e sua amada aeronave... Fazem parte da rica história de nossa cidade agora.",
  ui_story_5010_50100601_84_dialog_content = "O que você fez?!",
  ui_story_5010_50100601_85_dialog_content = "Do que ele está falando, Lucas?",
  ui_story_5010_50100601_86_dialog_content = "Você não o ouviu? Rhein está começando uma rebelião!",
  ui_story_5010_50100601_87_dialog_content = "Droga... Nossos terminais não estão funcionando! Isso deve ser obra de Rhein...",
  ui_story_5010_50100601_88_dialog_content = "Precisamos encontrar uma maneira de divulgar a notícia!",
  ui_story_5010_50100601_89_dialog_content = "Mas de onde vem a confiança de Rhein? Ele realmente acha que pode vencer todos os chefes aqui?",
  ui_story_5010_50100601_90_dialog_content = "Olha lá, Lucas!",
  ui_story_5010_50100601_91_dialog_content = "Céus... São muitos Eclipsites transformados!",
  ui_story_5010_50100601_92_dialog_content = "Por favor, abstenha-se de quaisquer atos inúteis de resistência!",
  ui_story_5010_50100601_93_dialog_content = "Como representante da Blue Lion Guild... Não, de TODA Umbraton... Por favor, aceite minhas sinceras desculpas por esta cena desordenada.",
  ui_story_5010_50100601_94_dialog_content = "Agora, queridos líderes das muitas Guildas de Umbraton, bem como todos os outros estimados convidados de longe, eu humildemente exijo sua rendição incondicional e a aceitação dos seguintes termos!",
  ui_story_5010_50100601_95_dialog_content = "Lucas, nós...",
  ui_story_5010_50100601_96_dialog_content = "Vou te cobrir enquanto você procura uma saída. Depois disso, cabe a você conseguir ajuda para todos nós.",
  ui_story_5010_50100601_97_dialog_content = "Eh? O que você está fazendo?!",
  ui_story_5010_50100601_98_dialog_content = "...?",
  ui_story_5010_50100601_99_dialog_content = "Parece... Você não precisa mais desse braço!",
  ui_story_5010_50100601_100_dialog_content = "Aaaaaaaargh!!!",
  ui_story_5010_50100601_101_dialog_content = "A Verdadeira Ordem...?",
  ui_story_5010_50100601_102_dialog_content = "...",
  ui_story_5010_50100601_103_dialog_content = "Era para ser um leilão normal e você estragou tudo...",
  ui_story_5010_50100601_104_dialog_content = "C-Calma, Paloma! Você já o deixou inconsciente...",
  ui_story_5010_50100601_105_dialog_content = "Sr. Rhein, as regras proíbem qualquer tipo de perturbação ruidosa nestes leilões. Receio... Teremos que pedir para você sair.",
  ui_story_5010_50100601_106_dialog_content = "... E quem pode ser voce? Eu deveria saber quem você é?",
  ui_story_5010_50100601_107_dialog_content = "Chega dessa bobagem. Mate todos.",
  ui_story_5010_50100601_108_dialog_content = "Berilo! Paloma!",
  ui_story_5010_50100601_109_dialog_content = "PlayerName?!",
  ui_story_5010_50100601_110_dialog_content = "Nos encontramos de novo, meu amigo. Uma pena que tenha que ser em circunstâncias tão terríveis.",
  ui_story_5010_50100601_111_dialog_content = "Você de novo, celestita... Mas para onde foram seus associados?",
  ui_story_5010_50100601_112_dialog_content = "...",
  ui_story_5010_50100601_113_dialog_content = "... Ah, mas suponho que isso era de se esperar. Eu não queria recorrer à violência, sabe?",
  ui_story_5010_50100601_114_dialog_content = "Aff.",
  ui_story_5010_50100601_115_dialog_content = "Vou me desfazer dos que estão aqui. Você pode ficar com o resto.",
  ui_story_5010_50100601_116_dialog_content = "Sim, senhor!",
  ui_story_5010_50100601_117_dialog_content = "Aqui, pegue isso também.",
  ui_story_5010_50100601_118_dialog_content = "Ah! Obrigado, chefe! Todas essas coisas boas...",
  ui_story_5010_50100601_119_dialog_content = "Não desperdice um único comprimido! Para a nova ordem de Umbraton!",
  ui_story_5010_50100601_120_dialog_content = "Grrrrr!",
  ui_story_5010_50100601_121_dialog_content = "Aquele homem... Ele acabou de se transformar em um Eclipsite?!",
  ui_story_5010_50100601_122_dialog_content = "Pedidos, PlayerName!",
  ui_story_5010_50100601_123_dialog_content = "Deixe para mim! Faust, certifique-se de que aqueles dois não fujam!",
  ui_story_5010_50100601_124_dialog_content = "O que é isso? Você quer nos capturar?",
  ui_story_5010_50100601_125_dialog_content = "Hahahaha! Que garoto corajoso!",
  ui_story_5010_50100601_126_dialog_content = "Ei, por que você está rindo? Eu tenho algumas perguntas para você, agora venha aqui!",
  ui_story_5010_50100601_127_dialog_content = "Fique para trás, sua louca.",
  ui_story_5010_50100601_128_dialog_content = "Do que você me chamou...?",
  ui_story_5010_50100601_129_dialog_content = "*Suspiro* Isso vai ficar feio.",
  ui_story_5010_50100602_1_dialog_content = "... Condenar!",
  ui_story_5010_50100602_2_dialog_content = "Uraaagh...!",
  ui_story_5010_50100602_3_dialog_content = "Ah... Pittman! Você está aqui!",
  ui_story_5010_50100602_4_dialog_content = "Pittman?",
  ui_story_5010_50100602_5_dialog_content = "Boa noite para você também, Paloma...",
  ui_story_5010_50100602_6_dialog_content = "Cristal sanguíneo... Pertence a Beryl Gautier!",
  ui_story_5010_50100602_7_dialog_content = "Olá! Eu ouvi muito sobre você, Sr. Investigador!",
  ui_story_5010_50100602_8_dialog_content = "Senhorita Beryl Gautier... Eu sou Wayne Pittman do Lumo Hall of Justice, devo insistir que você venha comigo neste instante...",
  ui_story_5010_50100602_9_dialog_content = "Você está... me prendendo?",
  ui_story_5010_50100602_10_dialog_content = "Parece que você não fez nenhum progresso em sua investigação, Pittman...",
  ui_story_5010_50100602_11_dialog_content = "É... Paloma? Pittman não veio aqui por vocês. Ele está aqui por causa de...",
  ui_story_5010_50100602_12_dialog_content = "Os potenciadores, ou mais precisamente, as pílulas que aqueles membros da Blue Lion Guild acabaram de engolir...",
  ui_story_5010_50100602_13_dialog_content = "Espere, do que você está falando?",
  ui_story_5010_50100602_14_dialog_content = "Paloma... Temo que a técnica de modificação de Mirren Gautier esteja de alguma forma ligada a esses intensificadores.",
  ui_story_5010_50100602_15_dialog_content = "Mirren Gautier...",
  ui_story_5010_50100602_16_dialog_content = "Precisamos parar com isso agora. O mais importante, por enquanto, não é a discussão.",
  ui_story_5010_50100602_17_dialog_content = "Para onde foi Rhein? Ou aquele cara com a bengala, aliás?",
  ui_story_5010_50100602_18_dialog_content = "Eles devem ter escapado.",
  ui_story_5010_50100602_19_dialog_content = "Mas por que eles escolheriam este leilão como alvo de seu ataque?",
  ui_story_5010_50100602_20_dialog_content = "Receio que a resposta não seja tão fácil. Tudo isso deve fazer parte do plano deles.",
  ui_story_5010_50100602_21_dialog_content = "Estamos ficando sem tempo. Temos que...",
  ui_story_5010_50100602_22_dialog_content = "Com licença, amigos. Mas encontrei o que procurávamos.",
  ui_story_5010_50100602_23_dialog_content = "Você achou?",
  ui_story_5010_50100602_24_dialog_content = "Visto que a Blue Lion Guild já violou as regras do leilão...",
  ui_story_5010_50100602_25_dialog_content = "Achei que poderíamos conseguir o que queremos e ir agora.",
  ui_story_5010_50100602_26_dialog_content = "Sinto muito, PlayerName, mas acredito que essas senhoras e eu devemos seguir caminhos separados por enquanto.",
  ui_story_5010_50100602_27_dialog_content = "Talvez nos veremos novamente em breve... Que a Verdade os abençoe.",
  ui_story_5010_50100602_28_dialog_content = "T-tchau, PlayerName...",
  ui_story_5010_50100602_29_dialog_content = "Oh! Uh, t-cuidem-se, vocês três!",
  ui_story_5010_50100602_30_dialog_content = "Eles já se foram... Todos na Verdadeira Ordem vêm e vão como o vento?",
  ui_story_5010_50100602_31_dialog_content = "Beryl Gautier! Volte, Beryl Gautier...!",
  ui_story_5010_50100602_32_dialog_content = "Ah... Esqueça. Tenho certeza de que Rhein ainda tem mais reservado para todos nós, PlayerName.",
  ui_story_5010_50100602_33_dialog_content = "Nossos terminais ainda estão fora do ar...",
  ui_story_5010_50100602_34_dialog_content = "Olhe para lá. É um sinal de fumaça e está vindo da direção da Sede da Guilda!",
  ui_story_5010_50100602_35_dialog_content = "Em circunstâncias normais, as tropas da guarnição de Umbraton seriam enviadas imediatamente para controlar a situação.",
  ui_story_5010_50100602_36_dialog_content = "As tropas da guarnição de Umbraton podem realmente derrotar um Enhancer?",
  ui_story_5010_50100602_37_dialog_content = "Er... Sinceramente? Acho que eles não têm chance.",
  ui_story_5010_50100602_38_dialog_content = "Devemos ir até o quartel-general e verificar a situação.",
  ui_story_5010_50100602_39_dialog_content = "Eu concordo... Mostre o caminho, Luke!",
  ui_story_5010_50100602_40_dialog_content = "Vem comigo!",
  ui_story_5010_50100701_1_dialog_content = "A Verdadeira Ordem... Eles são ainda mais problemáticos do que eu esperava.",
  ui_story_5010_50100701_2_dialog_content = "No entanto, o plano está em andamento e a vitória está próxima.",
  ui_story_5010_50100701_3_dialog_content = "Parece que sim, mas prefiro não jogar nossa final <color=#FFB400>carta de trunfo</color>.",
  ui_story_5010_50100701_4_dialog_content = "Senhora Betel! Obrigado Senhor! Você tem que salvar...!",
  ui_story_5010_50100701_5_dialog_content = "Hahahahaha!",
  ui_story_5010_50100701_6_dialog_content = "Quem é Você? Como você ousa atacar a Sede da Guilda Umbraton!",
  ui_story_5010_50100701_7_dialog_content = "Heh... Estamos apenas agindo sob as ordens do novo Shadowlord! A Sede da Guilda Umbraton pertence a ele agora!",
  ui_story_5010_50100701_8_dialog_content = "... Você tem alguma ideia do que acabou de dizer?",
  ui_story_5010_50100701_9_dialog_content = "Ah, claro que sim, sua tola! Hoje é o dia que você morre!!",
  ui_story_5010_50100701_10_dialog_content = "Parece que todos vocês estão preparados para morrer por sua causa.",
  ui_story_5010_50100701_11_dialog_content = "Nesse caso...",
  ui_story_5010_50100701_12_dialog_content = "... Ai!!",
  ui_story_5010_50100701_13_dialog_content = "Estou feliz em obrigar.",
  ui_story_5010_50100701_14_dialog_content = "Não pensamos que seria você a responder ao nosso sinal de socorro, Lady Bethel...",
  ui_story_5010_50100701_15_dialog_content = "Havia tantos deles agora. Eles disseram que o novo Shadowlord estava no controle de tudo, e que nós...",
  ui_story_5010_50100701_16_dialog_content = "Espere... Cuidado, pessoal!",
  ui_story_5010_50100701_17_dialog_content = "Esse sentimento... O sentimento de poder avassalador! Hahahaha!!!",
  ui_story_5010_50100701_18_dialog_content = "A luta parece intensa... Os invasores já devem ter entrado no salão principal.",
  ui_story_5010_50100701_19_dialog_content = "Essa era a voz de Betel agora há pouco!",
  ui_story_5010_50100701_20_dialog_content = "Espere... Estou tendo aquela sensação estranha de novo... É...?",
  ui_story_5010_50100701_21_dialog_content = "Isso é! Eles estão usando potenciadores de novo!",
  ui_story_5010_50100701_22_dialog_content = "Bethel!",
  ui_story_5010_50100701_23_dialog_content = "PlayerName! Estou aqui!",
  ui_story_5010_50100701_24_dialog_content = "Dez vezes... Não, vinte vezes... Todos vocês, olhem bem!",
  ui_story_5010_50100701_25_dialog_content = "Quantas pílulas aquele cara tomou?",
  ui_story_5010_50100701_26_dialog_content = "Estamos chegando, Betel! Apenas espere!",
  ui_story_5010_50100801_1_dialog_content = "Betel! Esses caras são os homens de Maude! Ele e Rhein atacaram o leilão clandestino agora mesmo!",
  ui_story_5010_50100801_2_dialog_content = "Rhein disse que o Shadowlord... já era história.",
  ui_story_5010_50100801_3_dialog_content = "Quando você disse que o Shadowlord havia sido atacado antes, o que você...",
  ui_story_5010_50100801_4_dialog_content = "Ainda não fiz contato com ele, e as pessoas que mandei procurá-lo ainda não mandaram notícias.",
  ui_story_5010_50100801_5_dialog_content = "Tudo o que sei é que houve um acidente com a aeronave do Shadowlord...",
  ui_story_5010_50100801_6_dialog_content = "Então por que você está aqui na sede?",
  ui_story_5010_50100801_7_dialog_content = "Vi o sinal de socorro à distância e vim o mais rápido que pude.",
  ui_story_5010_50100801_8_dialog_content = "Senhora Betel! Somos os socorristas da guarnição...",
  ui_story_5010_50100801_9_dialog_content = "Eu sei eu sei. Você nos trouxe alguma notícia?",
  ui_story_5010_50100801_10_dialog_content = "A Blue Lion Guild, em conjunto com a Solus, deu um golpe total.",
  ui_story_5010_50100801_11_dialog_content = "Os alvos de sua insurgência armada incluem todas as principais guildas, um leilão clandestino e a mansão do Shadowlord...",
  ui_story_5010_50100801_12_dialog_content = "As medidas de emergência já foram implementadas e...",
  ui_story_5010_50100801_13_dialog_content = "Alguém conseguiu entrar em contato com o próprio Shadowlord?",
  ui_story_5010_50100801_14_dialog_content = "Devido ao clima anormal de hoje, todos os terminais da cidade estão inoperantes. Não conseguimos estabelecer contato com o Shadowlord, mas os rumores mencionam que Rhein já...",
  ui_story_5010_50100801_15_dialog_content = "O suficiente. Continue com seu trabalho.",
  ui_story_5010_50100801_16_dialog_content = "E cuidado com esses monstros! Eles podem se transformar a qualquer momento!",
  ui_story_5010_50100801_17_dialog_content = "Você muito! Encontre uma maneira de restaurar as comunicações dentro da cidade. Precisamos verificar a situação em todos os setores e resgatar aqueles que ainda podem ser resgatados!",
  ui_story_5010_50100801_18_dialog_content = "M-Mas Lady Bethel, nossa principal diretriz é proteger o centro da cidade...",
  ui_story_5010_50100801_19_dialog_content = "...",
  ui_story_5010_50100801_20_dialog_content = "Sinto muito, mas foram ordens do Shadowlord. Adeus, Senhora Betel.",
  ui_story_5010_50100801_21_dialog_content = "Heh, isso é Lord Istvan para você.",
  ui_story_5010_50100801_22_dialog_content = "Rhein e seus homens perderam a cabeça? Quanto poder eles poderiam ter, para serem confiantes o suficiente para desafiar todo Umbraton de uma vez?",
  ui_story_5010_50100801_23_dialog_content = "Umbraton não é tão unificado quanto você imagina, Bethel.",
  ui_story_5010_50100801_24_dialog_content = "Cada guilda, cada gangue... inferno, cada pessoa mantém seus próprios interesses acima de tudo. Hehe...",
  ui_story_5010_50100801_25_dialog_content = "Estou disposto a apostar que cada organização está pensando em uma maneira de salvar a sua agora. Alguns podem até optar por ficar do lado de Rhein, neste momento.",
  ui_story_5010_50100801_26_dialog_content = "É por isso que ele escolheu atacar pessoalmente o leilão agora. Com todos os chefes importantes presentes, ele poderia envolver todos eles no caos.",
  ui_story_5010_50100801_27_dialog_content = "Sem o consentimento de Lumopolis, Rhein poderia realmente...",
  ui_story_5010_50100801_28_dialog_content = "Desculpe desapontá-lo, Meritíssimo... Mas aqui é Umbraton.",
  ui_story_5010_50100801_29_dialog_content = "Todos aqui seguem as regras de Umbraton para seu benefício. Todos mantêm as ordens por aqui por causa do poder de Istvan.",
  ui_story_5010_50100801_30_dialog_content = "No que diz respeito à maioria das pessoas, não importa quem age como o Shadowlord...",
  ui_story_5010_50100801_31_dialog_content = "Mas Rhein está jogando dessa forma muito violenta. Se ele assumir o controle da cidade, duvido que algo de bom saia disso.",
  ui_story_5010_50100801_32_dialog_content = "Mesmo que Rhein tenha realmente derrotado Istvan, e mesmo que ele conquiste todo Umbraton, Lumopolis nunca reconheceria...",
  ui_story_5010_50100801_33_dialog_content = "Eca! Não adianta falar disso agora! Nossa principal prioridade é encontrar o Shadowlord!",
  ui_story_5010_50100801_34_dialog_content = "Mas se as palavras de Rhein forem verdadeiras, Bethel, então o Shadowlord...",
  ui_story_5010_50100801_35_dialog_content = "Recuso-me a acreditar em nada disso, Luke!",
  ui_story_5010_50100801_36_dialog_content = "Mesmo que não importe quem atua como Shadowlord de Umbraton... Mas, por enquanto, não deve ser Rhein.",
  ui_story_5010_50100801_37_dialog_content = "Você está certo. Mais pessoas vão morrer se isso continuar. Temos que detê-lo, não importa o que ele queira.",
  ui_story_5010_50100801_38_dialog_content = "Irei reunir os visitantes de Lumopolis e encontrarei uma maneira de solicitar apoio da cidade.",
  ui_story_5010_50100801_39_dialog_content = "Veja! Esse sinal de fumaça é o que nossos mercenários usam em caso de emergência... E vem da direção do <color=#FFB400>Família Lin</color>!",
  ui_story_5010_50100801_40_dialog_content = "Eles não mantêm muitos combatentes na cidade, o que os torna um dos alvos mais fáceis de atacar.",
  ui_story_5010_50100801_41_dialog_content = "A defesa do centro da cidade é sólida. Mesmo Rhein teria dificuldade em romper.",
  ui_story_5010_50100801_42_dialog_content = "Huh? A Lin Guild pode estar sob ataque também?",
  ui_story_5010_50100801_43_dialog_content = "Eu tenho que ir ajudá-los!",
  ui_story_5010_50100801_44_dialog_content = "Meu trabalho ainda é te proteger, PlayerName. Se você for, eu vou.",
  ui_story_5010_50100801_45_dialog_content = "Todos se defendem sozinhos aqui em Umbraton... Receio que sejamos os únicos aqui que podem ajudar os outros.",
  ui_story_5010_50100801_46_dialog_content = "Vamos juntos então!",
  ui_story_5010_50100901_1_dialog_content = "V... você... Urgh...",
  ui_story_5010_50100901_2_dialog_content = "Silvo...",
  ui_story_5010_50100901_3_dialog_content = "Quem é?",
  ui_story_5010_50100901_4_dialog_content = "Este é um dos meus homens!",
  ui_story_5010_50100901_5_dialog_content = "L... Lucas?",
  ui_story_5010_50100901_6_dialog_content = "Você está bem, irmão? Quem fez isto para voce?!",
  ui_story_5010_50100901_7_dialog_content = "Eu vou sobreviver, mas Solus... Eles já conseguiram entrar.",
  ui_story_5010_50100901_8_dialog_content = "Os lutadores mais poderosos da Família Lin estão longe da cidade agora... Tudo o que eles podem fazer é contar com a defesa da cidade por enquanto. Não parece bom...",
  ui_story_5010_50100901_9_dialog_content = "Não se preocupe com isso agora. Apenas encontre um lugar seguro e descanse um pouco.",
  ui_story_5010_50100901_10_dialog_content = "...",
  ui_story_5010_50100901_11_dialog_content = "Lá dentro... Eles pegaram os potenciadores de novo!",
  ui_story_5010_50100901_12_dialog_content = "Temos que nos apressar!",
  ui_story_5010_50100901_13_dialog_content = "Parece que vamos ter que limpar o lugar todo, hein? Parece divertido.",
  ui_story_5010_50100901_14_dialog_content = "De fato. mal posso esperar...",
  ui_story_5010_50100901_15_dialog_content = "Corrente! Ampliar!",
  ui_story_5010_50100901_16_dialog_content = "*Rugido*",
  ui_story_5010_50100902_1_dialog_content = "A chuva está começando a cair forte agora.",
  ui_story_5010_50100902_2_dialog_content = "Espere até que a família Lin chegue em casa e veja a bagunça que ela se tornou...",
  ui_story_5010_50100902_3_dialog_content = "Bethel.",
  ui_story_5010_50100902_4_dialog_content = "Hum?",
  ui_story_5010_50100902_5_dialog_content = "Eu ainda não entendo... Por que a Blue Lion Guild uniria forças com Solus?",
  ui_story_5010_50100902_6_dialog_content = "Não parece que Rhein ou Maude realmente ganhem alguma coisa ao se unirem.",
  ui_story_5010_50100902_7_dialog_content = "Não só isso, mas eles já se enfrentaram muitas vezes no passado. Afinal, ambos operam principalmente no subsolo, então estão constantemente competindo um com o outro.",
  ui_story_5010_50100902_8_dialog_content = "Então, se é necessário que eles trabalhem juntos... por que não o fizeram antes?",
  ui_story_5010_50100902_9_dialog_content = "Por que eles escolheram esperar até hoje para lançar seu golpe...?",
  ui_story_5010_50100902_10_dialog_content = "O itinerário de viagem do Shadowlord. Ele deveria partir da cidade em seu dirigível esta manhã...",
  ui_story_5010_50100902_11_dialog_content = "Bem como esta tempestade peculiar.",
  ui_story_5010_50100902_12_dialog_content = "Padrões climáticos estranhos que interrompem as comunicações, bem como Eclipsites transformados... Já vi isso antes!",
  ui_story_5010_50100902_13_dialog_content = "Em Dunefire... Em Eraveil!",
  ui_story_5010_50100902_14_dialog_content = "Diga-me, Betel. O que você acha que poderia ter motivado aqueles dois a colocar tudo em risco assim?",
  ui_story_5010_50100902_15_dialog_content = "Não consigo imaginar que destruir a cidade assim os serviria de alguma forma...",
  ui_story_5010_50100902_16_dialog_content = "A menos que fosse para estabelecer o monopólio do comércio clandestino?",
  ui_story_5010_50100902_17_dialog_content = "Mas o Shadowlord sempre fechou os olhos para essas coisas. Ele nunca assumiu uma postura linha-dura contra eles.",
  ui_story_5010_50100902_18_dialog_content = "De fato, muitos produtos altamente questionáveis fluem livremente pelas sombras.",
  ui_story_5010_50100902_19_dialog_content = "É por isso...",
  ui_story_5010_50100902_20_dialog_content = "O que quer que motive seu golpe deve ser ainda mais atraente para eles do que um monopólio sobre o comércio clandestino.",
  ui_story_5010_50100902_21_dialog_content = "Mas o que pode ser...",
  ui_story_5010_50100902_22_dialog_content = "Desculpe interromper, Bethel, mas acho que Frankel...",
  ui_story_5010_50100902_23_dialog_content = "Fufufu...",
  ui_story_5010_50100902_24_dialog_content = "O que foi, Frankel?",
  ui_story_5010_50100902_25_dialog_content = "Boo-foo...",
  ui_story_5010_50100902_26_dialog_content = "O que é aquilo ali? Seu...",
  ui_story_5010_50100902_27_dialog_content = "Borboletas?",
  ui_story_5010_50100902_28_dialog_content = "Hã?",
  ui_story_5010_50100902_29_dialog_content = "Há um punhado de borboletas sob o beiral...",
  ui_story_5010_50100902_30_dialog_content = "Não é hora de observar a natureza, Luke.",
  ui_story_5010_50100902_31_dialog_content = "Você poderia, por favor, afastar sua ânsia de insetos e resgatar nossos companheiros aurorianos?",
  ui_story_5010_50100902_32_dialog_content = "... Algo aconteceu com a Gangue Steelfire.",
  ui_story_5010_50100902_33_dialog_content = "E-espere, quem é a Gangue Steelfire? E como você sabe que algo aconteceu com eles?",
  ui_story_5010_50100902_34_dialog_content = "Este tipo de borboleta é extremamente sensível a mudanças de temperatura. Não deveria existir aqui durante esta parte do ano.",
  ui_story_5010_50100902_35_dialog_content = "Mas a Steelfire Gang tinha uma estufa com alguns deles. Há algum tempo, aceitei um trabalho para consertar aquela mesma estufa.",
  ui_story_5010_50100902_36_dialog_content = "Olhe para o beiral e veja por si mesmo.",
  ui_story_5010_50100902_37_dialog_content = "Essas borboletas... Elas estão se abrigando da chuva aqui, e são atraídas pelo calor do nosso corpo.",
  ui_story_5010_50100902_38_dialog_content = "Há uma boa chance de que a estufa da Gangue Steelfire tenha sido aberta... Deve ser algum tipo de sinal!",
  ui_story_5010_50100902_39_dialog_content = "E um sinal que só você entenderia, Luke. Que estranho...",
  ui_story_5010_50100902_40_dialog_content = "O que vamos encontrar lá, eu me pergunto?",
  ui_story_5010_50100902_41_dialog_content = "Não há como dizer... Esta é a nossa única pista, afinal.",
  ui_story_5010_50100902_42_dialog_content = "De fato, mesmo apenas para ajudar a manter a ordem... Não podemos nos dar ao luxo de ficar de braços cruzados.",
  ui_story_5010_50100902_43_dialog_content = "Graças a Deus você estava aqui para pegar isso, Luke.",
  ui_story_5010_50100902_44_dialog_content = "Não é nada. Tenho pena dessas borboletas, no entanto.",
  ui_story_5010_50100902_45_dialog_content = "A esta temperatura... Eles só têm cerca de meia hora antes de morrer.",
  ui_story_5010_50100902_46_dialog_content = "A base da Gangue Steelfire fica em um terreno baixo, cercado por favelas.",
  ui_story_5010_50100902_47_dialog_content = "Se eles foram atacados, só posso imaginar a devastação...",
  ui_story_5010_50100902_48_dialog_content = "Não vamos descobrir ficando por aqui. Vamos.",
  ui_story_5010_50101002_1_dialog_content = "Graças a Deus... Conseguimos resgatar todos eles.",
  ui_story_5010_50101002_2_dialog_content = "Eu nunca teria imaginado que Rhein e Maude os deixaram intocados também.",
  ui_story_5010_50101002_3_dialog_content = "Isso não faz sentido... Parece que eles saíram às pressas antes de fazer o que vieram fazer.",
  ui_story_5010_50101002_4_dialog_content = "... Esqueça, precisamos cuidar dos feridos. Felizmente, seus ferimentos são relativamente pequenos.",
  ui_story_5010_50101002_5_dialog_content = "Deixei um sinal para os Mercenários da Chama Branca, eles devem estar aqui para fornecer suporte a qualquer minuto.",
  ui_story_5010_50101002_6_dialog_content = "Como você conseguiu contatá-los?",
  ui_story_5010_50101002_7_dialog_content = "Deixei atrás de nós um rastro de misturas especiais, que não desaparecem na chuva e até brilham no escuro.",
  ui_story_5010_50101002_8_dialog_content = "... Deve ter algo a ver com seus insetos, imagino?",
  ui_story_5010_50101002_9_dialog_content = "Isso mesmo!",
  ui_story_5010_50101002_10_dialog_content = "Espere, o que está acontecendo aqui...",
  ui_story_5010_50101002_11_dialog_content = "Corre! Faça para o topo!",
  ui_story_5010_50101002_12_dialog_content = "Para onde a Gangue Steelfire fugiu? Ninguém pode nos salvar agora!",
  ui_story_5010_50101002_13_dialog_content = "Quem disse?",
  ui_story_5010_50101002_14_dialog_content = "Este lugar... O cheiro do mar profundo permeia este lugar.",
  ui_story_5010_50101002_15_dialog_content = "Esses suprimentos de emergência são para todos vocês!",
  ui_story_5010_50101002_16_dialog_content = "Balsas, dispositivos de flutuação e rações de emergência!",
  ui_story_5010_50101002_17_dialog_content = "Ouçam!",
  ui_story_5010_50101002_18_dialog_content = "Não pegue todos os suprimentos como cachorrinhos famintos!",
  ui_story_5010_50101002_19_dialog_content = "É a Gangue Istvan! Istvan Gang veio em nosso socorro!",
  ui_story_5010_50101002_20_dialog_content = "Excelente! Agora que você está aqui!",
  ui_story_5010_50101002_21_dialog_content = "O Shadowlord ordenou que você defendesse este lugar?",
  ui_story_5010_50101002_22_dialog_content = "Diga-me, ele está são e salvo?",
  ui_story_5010_50101002_23_dialog_content = "Quem sabe? As sombras podem ser lavadas pela chuva, Betel?",
  ui_story_5010_50101002_24_dialog_content = "Estamos consertando de cima a baixo, chefe!",
  ui_story_5010_50101002_25_dialog_content = "Qual é a situação nas outras partes da cidade?",
  ui_story_5010_50101002_26_dialog_content = "Sabemos quantas vítimas houve? Onde estão Solus e os Leões Azuis agora? Algum de vocês viu Maude ou Rhein?",
  ui_story_5010_50101002_27_dialog_content = "... Muitas perguntas.",
  ui_story_5010_50101002_28_dialog_content = "Ainda não há muitas baixas, nenhuma ideia de onde estão, e não, não as vimos.",
  ui_story_5010_50101002_29_dialog_content = "Cuidar dos feridos já é bastante cansativo. Sem mais perguntas.",
  ui_story_5010_50101002_30_dialog_content = "Porém, as guildas que estavam sob ataque anteriormente estão sob nossa proteção agora!",
  ui_story_5010_50101002_31_dialog_content = "Os números do inimigo estão começando a diminuir também...",
  ui_story_5010_50101002_32_dialog_content = "Eles devem ter se assustado com nossa presença heróica. Sim, deve ser isso.",
  ui_story_5010_50101002_33_dialog_content = "Espere... Você está me dizendo que não há mais nenhum membro da Solus na cidade?",
  ui_story_5010_50101002_34_dialog_content = "Isso não combina com seus movimentos anteriores...",
  ui_story_5010_50101002_35_dialog_content = "Sou só eu, ou o nível da água está ficando cada vez mais alto aqui?",
  ui_story_5010_50101002_36_dialog_content = "Acho que sim... Meus tentáculos não conseguem parar.",
  ui_story_5010_50101002_37_dialog_content = "A água... Está começando a correr aqui dentro!!",
  ui_story_5010_50101002_38_dialog_content = "As favelas estão em terrenos baixos.",
  ui_story_5010_50101002_39_dialog_content = "Temos sorte que Istvan Gang está aqui para ajudar...",
  ui_story_5010_50101002_40_dialog_content = "Não consigo imaginar o problema que essas pessoas teriam se não fosse por vocês.",
  ui_story_5010_50101002_41_dialog_content = "Oh não!",
  ui_story_5010_50101002_42_dialog_content = "Se a chuva continuar caindo assim, os navios e as docas do Rio do Ouro estarão em perigo!",
  ui_story_5010_50101002_43_dialog_content = "A água... as favelas... docas e navios... E toda essa chuva...",
  ui_story_5010_50101002_44_dialog_content = "Ah! Então é isso que está acontecendo! Eu finalmente entendo!",
  ui_story_5010_50101002_45_dialog_content = "<size=45><color=#FFB400>A Represa das Cicatrizes!</color></size>",
  ui_story_5010_50101002_46_dialog_content = "Esse é o alvo deles! É a Represa das Cicatrizes!",
  ui_story_5010_50101002_47_dialog_content = "... Entendo!",
  ui_story_5010_50101002_48_dialog_content = "Se a barragem estourasse...",
  ui_story_5010_50101002_49_dialog_content = "Umbraton sofrerá baixas massivas. Não apenas as favelas serão completamente destruídas, mas as docas essenciais da cidade também serão fortemente danificadas.",
  ui_story_5010_50101002_50_dialog_content = "Isso... isso é muito pior do que qualquer coisa que eu imaginei!",
  ui_story_5010_50101002_51_dialog_content = "Como podemos saber o estado da barragem neste momento?",
  ui_story_5010_50101002_52_dialog_content = "A julgar pela quantidade de água aqui, é seguro dizer que não foi atingido de forma crítica.",
  ui_story_5010_50101002_53_dialog_content = "Mas precisamos nos mexer, e rápido!",
  ui_story_5010_50101101_1_dialog_content = "A barragem está logo à frente. Vamos explorar a área primeiro.",
  ui_story_5010_50101101_2_dialog_content = "*Suspiro* Pronto! É a Maude!",
  ui_story_5010_50101101_3_dialog_content = "... A barragem já foi furada!",
  ui_story_5010_50101101_4_dialog_content = "Parece que não vai aguentar por muito mais tempo...",
  ui_story_5010_50101101_5_dialog_content = "Você viu aquilo? Eles estão usando armas de fogo.",
  ui_story_5010_50101101_6_dialog_content = "Depressa, antes que seja tarde demais!",
  ui_story_5010_50101101_7_dialog_content = "Senhor Maude! Senhor Rhein!",
  ui_story_5010_50101101_8_dialog_content = "Oh? Afinal, eles nos encontraram.",
  ui_story_5010_50101101_9_dialog_content = "Você está aqui para testemunhar a queda da represa também, Lady Bethel?",
  ui_story_5010_50101101_10_dialog_content = "Mas não se preocupe. Você se reunirá com seu amado pai, Lorde Istvan, em breve.",
  ui_story_5010_50101101_11_dialog_content = "Chega de brincadeira. Ataque!",
  ui_story_5010_50101101_12_dialog_content = "Como se tivéssemos deixado você se safar dessa!",
  ui_story_5010_50101101_13_dialog_content = "Nem em seus sonhos, seus traidores!",
  ui_story_5010_50101101_14_dialog_content = "Você cuida dessas pragas insignificantes.",
  ui_story_5010_50101101_15_dialog_content = "Tenho algo muito mais importante para fazer. Vai levar cada grama da minha concentração...",
  ui_story_5010_50101101_16_dialog_content = "Para preparar esta grande surpresa para todos de Umbraton.",
  ui_story_5010_50101101_17_dialog_content = "Não vou deixar você destruir a represa!",
  ui_story_5010_50101101_18_dialog_content = "Uwaaaa!!",
  ui_story_5010_50101101_19_dialog_content = "Devo realmente lidar com essa escória da lagoa eu mesmo...?",
  ui_story_5010_50101101_20_dialog_content = "Acho que devo me aquecer primeiro...",
  ui_story_5010_50101101_21_dialog_content = "Aproveitando o sabor da sua luta final e sem sentido!",
  ui_story_5010_50101101_22_dialog_content = "Vocês dois parecem estar muito animados.",
  ui_story_5010_50101101_23_dialog_content = "<size=45>V... Você...?!</size>",
  ui_story_5010_50101101_24_dialog_content = "<size=45>Como... Como você ainda está vivo?!</size>",
  ui_story_5010_50101101_25_dialog_content = "Você deveria ter explodido em pedaços!",
  ui_story_5010_50101101_26_dialog_content = "Maude... Devo dizer que falta decoro na sua maneira de receber um novo hóspede.",
  ui_story_5010_50101101_27_dialog_content = "Destruir meu dirigível só me deu alguns arranhões, nada mais...",
  ui_story_5010_50101101_28_dialog_content = "O fato de eu estar diante de você agora... é uma prova do completo e absoluto fracasso de seus esforços.",
  ui_story_5010_50101101_29_dialog_content = "Todos os membros da Solus responsáveis pelo conflito na cidade foram presos, assim como seus cúmplices.",
  ui_story_5010_50101101_30_dialog_content = "Hahaha... devo admitir, aqueles monstros transformadores foram bastante desafiadores, mas...",
  ui_story_5010_50101101_31_dialog_content = "Solus não existe mais, e a Blue Lion Guild compartilhará o mesmo destino.",
  ui_story_5010_50101101_32_dialog_content = "Seus bens serão distribuídos uniformemente para o resto de Umbraton, como compensação pelos problemas que você causou. Em nome dos líderes da cidade... gostaria de agradecer de coração a sua generosa doação! Hahahahaha!",
  ui_story_5010_50101101_33_dialog_content = "Você acha que pode nos parar com suas palavras sem sentido?",
  ui_story_5010_50101101_34_dialog_content = "Receio que ele esteja dizendo a verdade. Olhe para os sinais de fumaça subindo da cidade...",
  ui_story_5010_50101101_35_dialog_content = "Parece que devemos mudar de estratégia, Maude...",
  ui_story_5010_50101101_36_dialog_content = "Este é o fim da linha para você, Rhein.",
  ui_story_5010_50101101_37_dialog_content = "Quanto a mim... eu, e só eu, sou mais do que suficiente!!",
  ui_story_5010_50101101_38_dialog_content = "Farei deste lugar o lugar de descanso final para cada pessoa aqui!!!",
  ui_story_5010_50101101_39_dialog_content = "Poder... Poder infinito... É meu!!!",
  ui_story_5010_50101101_40_dialog_content = "Lá vem... Maude vai tomar aqueles comprimidos!",
  ui_story_5010_50101101_41_dialog_content = "H-Ele fez isso... Maude comeu todos... Ele parece completamente diferente dos outros que os pegaram!",
  ui_story_5010_50101101_42_dialog_content = "O que é essa pressão intensa?!",
  ui_story_5010_50101101_43_dialog_content = "<anim type=Shake><size=45>Gaaaaaaaaa!!!</size></anim>",
  ui_story_5010_50101101_44_dialog_content = "<anim type=Shake><size=45>Poder...</size></anim>",
  ui_story_5010_50101101_45_dialog_content = "Juntos, todos! Ataque!",
  ui_story_5010_50101101_46_dialog_content = "Pai, você ainda está ferido. Vamos lutar contra Maude. Por favor, faça o que puder para proteger a represa!",
  ui_story_5010_50101101_47_dialog_content = "À sua esquerda, Lucas!",
  ui_story_5010_50101101_48_dialog_content = "Cuidado, ele está prestes a atacar!",
  ui_story_5010_50101101_49_dialog_content = "Finalmente... Finalmente chegou a hora.",
  ui_story_5010_50101101_50_dialog_content = "Ouçam meus comandos, todos!!!",
  ui_story_5010_50101201_1_dialog_content = "Você está atrasado, PlayerName. O Shadowlord está esperando por você todo esse tempo!",
  ui_story_5010_50101201_2_dialog_content = "Oh! R-Sério? Corri o mais rápido que pude...",
  ui_story_5010_50101201_3_dialog_content = "Embora eu suponha que com colheitas escassas como esta, seu atraso pode ser desculpado.",
  ui_story_5010_50101201_4_dialog_content = "Mataria você dizer a verdade, pelo menos uma vez? Seus tentáculos não vão cair se você fizer isso, sabe?",
  ui_story_5010_50101201_5_dialog_content = "Ah... eu sabia que não estava atrasada!",
  ui_story_5010_50101201_6_dialog_content = "Ah...! E-espere, fique para trás! Ainda tenho outras coisas para cuidar!",
  ui_story_5010_50101201_7_dialog_content = "Estes são os documentos de transferência de propriedade para todos os ativos da Caelestite, PlayerName. Eles exigirão sua assinatura.",
  ui_story_5010_50101201_8_dialog_content = "Além disso, de acordo com as instruções do Shadowlord... Gostaríamos de oferecer a você o <color=#FFB400>componentes da sala de simulação</color> do leilão, gratuitamente, como sinal de nossa gratidão.",
  ui_story_5010_50101201_9_dialog_content = "Luke, dos Mercenários da Chama Branca, concordou em entregar as referidas peças para Eraveil em um futuro próximo.",
  ui_story_5010_50101201_10_dialog_content = "Lucas! Você também está aqui!",
  ui_story_5010_50101201_11_dialog_content = "Nos encontramos de novo, vocês dois.",
  ui_story_5010_50101201_12_dialog_content = "Peço desculpas por interromper seu sincero reencontro.",
  ui_story_5010_50101201_13_dialog_content = "Pittman? O julgamento já foi concluído?",
  ui_story_5010_50101201_14_dialog_content = "Não é bem assim... vim me despedir. Minhas ordens são para escoltar Rhein de volta a Lumopolis para continuar seu julgamento.",
  ui_story_5010_50101201_15_dialog_content = "É um milagre que ele tenha conseguido sobreviver em primeiro lugar...",
  ui_story_5010_50101201_16_dialog_content = "Esperar. Rhein é um cidadão de Umbraton. Que direito você tem de levá-lo de volta para Lumopolis?",
  ui_story_5010_50101201_17_dialog_content = "Sinto muito... Mas essas ordens vêm de alguém muito acima de mim.",
  ui_story_5010_50101201_18_dialog_content = "Eu não poderia recusar, mesmo que quisesse.",
  ui_story_5010_50101201_19_dialog_content = "Mas...",
  ui_story_5010_50101201_20_dialog_content = "Devo acrescentar... Que o próprio Shadowlord também aprovou essas ordens.",
  ui_story_5010_50101201_21_dialog_content = "De fato. Desejo-lhe boa sorte, Pittman.",
  ui_story_5010_50101201_22_dialog_content = "Agradeço mais uma vez por sua compreensão... Shadowlord.",
  ui_story_5010_50101201_23_dialog_content = "PlayerName, Luke, Lady Bethel... Até o próximo encontro.",
  ui_story_5010_50101201_24_dialog_content = "... Pai.",
  ui_story_5010_50101201_25_dialog_content = "Senhor das Sombras.",
  ui_story_5010_50101201_26_dialog_content = "Hmm... O humor parece ter melhorado um pouco.",
  ui_story_5010_50101201_27_dialog_content = "Ah, mas claro... Afinal, o tempo melhorou.",
  ui_story_5010_50101201_28_dialog_content = "Istvan!",
  ui_story_5010_50101201_29_dialog_content = "Olá, PlayerName.",
  ui_story_5010_50101201_30_dialog_content = "Permita-me expressar minhas mais profundas desculpas. Você foi arrastado para os assuntos problemáticos de nossa cidade, e de uma maneira não pequena.",
  ui_story_5010_50101201_31_dialog_content = "H-Huh? Não foi nada mesmo... Não precisa se desculpar!",
  ui_story_5010_50101201_32_dialog_content = "Pai... O destino de Rhein pode ser tão facilmente...",
  ui_story_5010_50101201_33_dialog_content = "Você vai entender em breve, minha querida.",
  ui_story_5010_50101201_34_dialog_content = "U-Entender o que?",
  ui_story_5010_50101201_35_dialog_content = "Eu posso entender permitir que nossos adversários exponham sua conspiração, para que possamos juntar os pedaços depois...",
  ui_story_5010_50101201_36_dialog_content = "Mas não deveríamos ser nós a punir Rhein por seus crimes?",
  ui_story_5010_50101201_37_dialog_content = "Huh? Você chama de estratégia deixar as coisas saírem do controle?",
  ui_story_5010_50101201_38_dialog_content = "Ao permitir que Rhein mostre todas as suas cartas, evitamos dar a ele a oportunidade de continuar tramando nas sombras e impedimos que ele e seus companheiros causem mais problemas no futuro.",
  ui_story_5010_50101201_39_dialog_content = "Mas se não tivéssemos conseguido controlar a situação no final... Muitas pessoas não teriam morrido por causa disso?",
  ui_story_5010_50101201_40_dialog_content = "Pessoas com corações puros e ingênuos não podem sobreviver aqui em Umbraton... Especialmente em uma posição de poder.",
  ui_story_5010_50101201_41_dialog_content = "Talvez tenha sido um teste para Betel? Afinal, tenho certeza de que Lorde Istvan pensou muito sobre quem o sucederia no futuro...",
  ui_story_5010_50101201_42_dialog_content = "Chega disso. De qualquer forma, há uma chance de ele receber uma sentença mais leve em Lumopolis, muito menos do que ele merece.",
  ui_story_5010_50101201_43_dialog_content = "Não é apenas uma possibilidade. Eu honestamente ficaria surpreso se eles não aliviassem sua sentença.",
  ui_story_5010_50101201_44_dialog_content = "Hã?",
  ui_story_5010_50101201_45_dialog_content = "Se eles quiserem executar ou punir severamente um criminoso, Umbraton é o lugar para isso. Então, por que eles precisariam levá-lo de volta para Lumopolis?",
  ui_story_5010_50101201_46_dialog_content = "Não importa o quão forte Rhein fosse, se ele não tivesse algum tipo de ajuda nos bastidores de Lumopolis...",
  ui_story_5010_50101201_47_dialog_content = "Mesmo que ele conseguisse nos derrotar, ele não seria capaz de agir como Shadowlord por muito tempo.",
  ui_story_5010_50101201_48_dialog_content = "Se aqueles jogadores ocultos ainda não querem Rhein morto, tenho certeza de que não permitirão que ele seja executado.",
  ui_story_5010_50101201_49_dialog_content = "Estou certo, Meritíssimo?",
  ui_story_5010_50101201_50_dialog_content = "Eu entendo suas palavras, mas este é um tópico que eu prefiro evitar discutir.",
  ui_story_5010_50101201_51_dialog_content = "Senhora Bethel, posso assegurar-lhe que a decisão de Lorde Istvan é uma que ele pensou muito. Por favor, não fique tão chateado com isso.",
  ui_story_5010_50101201_52_dialog_content = "Ele é provavelmente a pessoa mais racional, por ter estado nesta posição por tanto tempo.",
  ui_story_5010_50101201_53_dialog_content = "Eu posso entender isso, mas ainda me recuso a aceitá-lo.",
  ui_story_5010_50101201_54_dialog_content = "Seja Lumopolis ou Umbraton... seus esquemas se aprofundam a cada dia.",
  ui_story_5010_50101201_55_dialog_content = "Mais uma coisa, PlayerName. Minha investigação sobre os intensificadores ainda está em andamento. Tenho certeza de que precisarei de sua ajuda no futuro.",
  ui_story_5010_50101201_56_dialog_content = "Isso não é óbvio? As pessoas estão cooperando com o Eclipse e...",
  ui_story_5010_50101201_57_dialog_content = "Devo pedir que você se abstenha de fazer qualquer alegação sem fundamento antes de obtermos as evidências adequadas. Encontrar a verdade exigirá muita paciência.",
  ui_story_5010_50101201_58_dialog_content = "*Suspiro* Está bem.",
  ui_story_5010_50101201_59_dialog_content = "Continuarei a rastrear os aliados restantes de Rhein em Umbraton. Vamos pegar cada um desses canalhas.",
  ui_story_5010_50101201_60_dialog_content = "O custo da rebelião foi muito grave. Não podemos deixar isso acontecer de novo.",
  ui_story_5010_50101201_61_dialog_content = "Bethel, Rhein não foi a primeira pessoa a desafiar Istvan, nem será a última.",
  ui_story_5010_50101201_62_dialog_content = "A julgar por este resultado, Istvan é forte o suficiente para lidar com a situação, então todos devem continuar a manter a ordem aqui.",
  ui_story_5010_50101201_63_dialog_content = "Todos os esquadrões de mercenários, gangues e guildas...",
  ui_story_5010_50101201_64_dialog_content = "Ah, guildas... A propósito, Luke, qual é a situação da família Lin?",
  ui_story_5010_50101201_65_dialog_content = "Eu já perguntei. Os principais membros da família Lin estão escavando uma relíquia misteriosa e não voltarão tão cedo.",
  ui_story_5010_50101201_66_dialog_content = "Eu vejo. Terei que agradecer à família Lin quando tiver a chance.",
  ui_story_5010_50101201_67_dialog_content = "Avisaremos assim que soubermos de algo.",
  ui_story_5010_50101201_68_dialog_content = "Bem, é hora de dizer adeus a todos vocês.",
  ui_story_5010_50101201_69_dialog_content = "Prezado Naroxel:",
  ui_story_5010_50101201_70_dialog_content = "\"Então, isso resume nossa viagem a Umbraton... Embora eu tenha alguns arrependimentos...\"",
  ui_story_5010_50101201_71_dialog_content = "\"Ainda estou feliz por termos conseguido os componentes da sala de simulação...\"",
  ui_story_5010_50101201_72_dialog_content = "\"Seu uso específico ainda é desconhecido. Entrei em contato com vários especialistas científicos e tecnológicos...\"",
  ui_story_5010_50101201_73_dialog_content = "\"Obrigado novamente, Naroxel. E que a natureza cuide de você.\"",
  ui_story_5010_50101201_74_dialog_content = "\"Do seu amigo, PlayerName.\""
}
return config
